import { createGlobalStyle } from "styled-components";

/**
 * Light, institutional UAE-flag design system.
 * Brand red/green are used sparingly for brand + interactive accents; the
 * risk/heat ramp is a separate sequential scale so brand never reads as risk.
 */
export const GlobalStyle = createGlobalStyle`
  :root {
    color-scheme: dark;

    /* ground + panels (deep UAE green, a touch lighter than DHDE) */
    --bg: #06200f;
    --bg-2: #082614;
    --panel-solid: #0c2e1b;
    --panel-2: #113a24;
    --panel-3: #174a2f;
    /* UAE black glass = floating overlays on the map (neutral, not green-tinted) */
    --panel: rgba(11, 11, 12, 0.82);
    --glass: rgba(11, 11, 12, 0.82);
    /* neutral white-alpha borders for black-glass overlays */
    --glass-border: rgba(255, 255, 255, 0.08);
    --glass-border-strong: rgba(255, 255, 255, 0.14);

    /* ink + neutrals */
    --ink: #ffffff;
    --ink-2: #d3eadb;
    --muted: #93b8a2;
    --faint: #6f977f;
    --border: rgba(0, 151, 57, 0.22);
    --border-strong: rgba(0, 151, 57, 0.42);
    --line: rgba(255, 255, 255, 0.1);

    /* UAE green (fills) + bright green (text on dark) */
    --green: #00843d;
    --green-ink: #3ccf7e;
    --green-soft: rgba(0, 132, 61, 0.2);
    --accent: #00843d;
    --accent-ink: #3ccf7e;
    --accent-soft: rgba(0, 132, 61, 0.2);

    /* UAE red = structural accent only (DHDE's gold role), never risk */
    --red: #ef3340;
    --red-ink: #ff7a82;
    --red-soft: rgba(239, 51, 64, 0.14);

    /* legacy "navy" aliases kept green so existing refs stay on-theme */
    --navy: #3ccf7e;
    --navy-2: #d3eadb;
    --navy-soft: rgba(0, 132, 61, 0.14);

    /* risk / heat ramp (NOT brand colors): Low..Critical */
    --risk-low: #ffe08a;
    --risk-moderate: #fdb833;
    --risk-elevated: #f3722c;
    --risk-high: #d62246;
    --risk-critical: #7a0b2e;

    /* provenance */
    --prov-real: #3dbb6e;
    --prov-modelled: #d7a84a;
    --prov-illustrative: #b58be0;
    --prov-pending: #8f9290;

    --shadow: 0 2px 14px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 18px 50px rgba(0, 0, 0, 0.55);
    --radius: 14px;
    --radius-sm: 10px;
    --radius-xs: 6px;
    --radius-pill: 999px;

    /* chart chrome (explicit hex - CSS vars do not resolve in SVG attributes) */
    --chart-tick: #93b8a2;
    --chart-grid: rgba(255, 255, 255, 0.08);

    --font-ui: "IBM Plex Sans", "IBM Plex Sans Arabic", -apple-system,
      BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --font-display: "Bricolage Grotesque", "IBM Plex Sans", -apple-system,
      "Segoe UI", sans-serif;
    --font-num: "IBM Plex Mono", "SF Mono", "Cascadia Mono", ui-monospace, monospace;
  }

  /* reusable DHDE-style eyebrow label (UAE red plays the gold role) */
  .eyebrow {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--red-ink);
  }
  .display {
    font-family: var(--font-display);
    letter-spacing: -0.015em;
  }

  /* UAE red flag-hoist bar before a heading (structural accent) */
  .hoist {
    position: relative;
    padding-top: 13px;
  }
  .hoist::before {
    content: "";
    position: absolute;
    top: 0;
    inset-inline-start: 0;
    width: 24px;
    height: 3px;
    border-radius: 2px;
    background: var(--red);
  }

  * { box-sizing: border-box; }

  body {
    background-color: var(--bg);
    color: var(--ink);
    margin: 0;
    padding: 0;
    font-family: var(--font-ui);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  #root {
    display: block;
    min-height: 100vh;
  }

  .dm-num {
    font-family: var(--font-num);
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.01em;
  }

  /* visible focus rings everywhere */
  :focus-visible {
    outline: 2px solid var(--green);
    outline-offset: 2px;
  }

  /* MapLibre controls + attribution, theme glass */
  .maplibregl-ctrl-attrib {
    font-size: 10px !important;
    background: rgba(11, 11, 12, 0.6) !important;
    border-radius: 8px !important;
  }
  .maplibregl-ctrl-attrib, .maplibregl-ctrl-attrib a { color: var(--muted) !important; }
  .maplibregl-popup-content {
    background: rgba(11, 11, 12, 0.92) !important;
    backdrop-filter: blur(10px) !important;
    color: var(--ink) !important;
    border: 1px solid var(--border-strong) !important;
    border-radius: 10px !important;
    box-shadow: var(--shadow-lg) !important;
  }
  .maplibregl-popup-tip {
    border-top-color: rgba(11, 11, 12, 0.92) !important;
    border-bottom-color: rgba(11, 11, 12, 0.92) !important;
  }

  /* slim scrollbars */
  ::-webkit-scrollbar { width: 8px; height: 8px; }
  ::-webkit-scrollbar-thumb {
    background: var(--border-strong);
    border-radius: 999px;
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.001ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.001ms !important;
    }
  }
`;
