/**
 * MODELLED what-if scenarios and interventions. Each scenario scales modelled
 * transmission; each intervention reduces it. Results (cases averted, peak
 * delay, demand reduction) come from deterministic model re-runs.
 */
import { simulateScenario, casesBetween } from "./forecast";

export interface Scenario {
  id: string;
  label: string;
  labelAr: string;
  betaMult: number;
}
export interface Intervention {
  id: string;
  label: string;
  labelAr: string;
  reduction: number;
}

export const SCENARIOS: Scenario[] = [
  { id: "baseline", label: "Baseline winter season", labelAr: "الموسم الشتوي الأساسي", betaMult: 1.0 },
  { id: "event", label: "Major event surge (WTC / Expo)", labelAr: "ذروة فعالية كبرى (المركز التجاري / إكسبو)", betaMult: 1.35 },
  { id: "nye", label: "New Year's Eve Downtown", labelAr: "ليلة رأس السنة في وسط المدينة", betaMult: 1.5 },
  { id: "travel", label: "Holiday travel peak (DXB)", labelAr: "ذروة سفر العطلات (مطار دبي)", betaMult: 1.3 },
  { id: "dust", label: "Dust storm (shamal) day", labelAr: "يوم عاصفة غبار (شمال)", betaMult: 1.18 },
];

export const INTERVENTIONS: Intervention[] = [
  { id: "airport", label: "Airport arrival screening", labelAr: "فحص الوافدين بالمطار", reduction: 0.12 },
  { id: "kiosks", label: "Extra screening kiosks", labelAr: "أكشاك فحص إضافية", reduction: 0.1 },
  { id: "masks", label: "Mask advisory at venues", labelAr: "إرشادات الكمامات بالفعاليات", reduction: 0.18 },
  { id: "schools", label: "School hygiene campaign", labelAr: "حملة نظافة المدارس", reduction: 0.08 },
  { id: "containment", label: "Containment zone on top hotspot", labelAr: "نطاق احتواء للبؤرة الأعلى", reduction: 0.2 },
];

export interface PlanResult {
  scenarioIndex: number[];
  intervenedIndex: number[];
  casesAverted: number;
  peakDelayDays: number;
  demandReductionPct: number;
}

/**
 * The single "recommended plan" shown as a headline figure on the Summary and
 * Insights pages. Memoised so every surface reports the same cases-averted value.
 */
export const RECOMMENDED_SCENARIO = "event";
export const RECOMMENDED_INTERVENTIONS = ["masks", "containment", "airport"];
let _recommended: PlanResult | null = null;
export const recommendedPlan = (): PlanResult =>
  _recommended || (_recommended = computePlan(RECOMMENDED_SCENARIO, RECOMMENDED_INTERVENTIONS));

export const computePlan = (scenarioId: string, interventionIds: string[]): PlanResult => {
  const sc = SCENARIOS.find((s) => s.id === scenarioId) || SCENARIOS[0];
  let keep = 1;
  INTERVENTIONS.forEach((iv) => {
    if (interventionIds.indexOf(iv.id) >= 0) keep *= 1 - iv.reduction;
  });
  const scenario = simulateScenario(sc.betaMult);
  const intervened = simulateScenario(sc.betaMult * keep);
  const casesAverted = casesBetween(scenario.attackRate, intervened.attackRate);
  const peakDelayDays = Math.max(0, intervened.peakIndex - scenario.peakIndex);
  const scPeak = Math.max.apply(null, scenario.index);
  const ivPeak = Math.max.apply(null, intervened.index);
  const demandReductionPct = scPeak > 0 ? Math.round(((scPeak - ivPeak) / scPeak) * 100) : 0;
  return {
    scenarioIndex: scenario.index,
    intervenedIndex: intervened.index,
    casesAverted,
    peakDelayDays,
    demandReductionPct,
  };
};
