import React from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import {
  ResponsiveContainer,
  ComposedChart,
  Area,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ReferenceLine,
  ReferenceDot,
  CartesianGrid,
} from "recharts";
import { cityCurve, cityRiskIndex, peakDay } from "../../model/forecast";

const Wrap = styled.div`
  height: 188px;
  margin: 0 -4px 6px;
`;
const Leg = styled.div`
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  font-size: 10.5px;
  color: var(--muted);
  padding: 0 2px 4px;
  span {
    display: inline-flex;
    align-items: center;
    gap: 5px;
  }
  i {
    width: 14px;
    height: 0;
    border-top: 2px solid;
  }
  i.band {
    height: 9px;
    border: 0;
    border-radius: 2px;
    background: rgba(243, 114, 44, 0.18);
  }
`;

const OBSERVED = "#ffffff";
const FORECAST = "#fdb833";

const ForecastChart: React.FC<{ day: number }> = ({ day }) => {
  const { t } = useTranslation();
  const data = cityCurve();
  const peak = peakDay();
  const peakVal = cityRiskIndex(peak);

  // dynamic y ceiling with headroom (never a flat line at 100)
  let dataMax = 0;
  data.forEach((p) => {
    const hi = Math.max(p.observed || 0, p.forecast || 0, p.band[1] || 0);
    if (hi > dataMax) dataMax = hi;
  });
  const yMax = Math.min(100, Math.max(40, Math.ceil((dataMax + 10) / 10) * 10));

  const fmt = (d: number): string => (d === 0 ? t("fc.now", { defaultValue: "Now" }) : d > 0 ? `+${d}` : `${d}`);

  return (
    <>
      <Wrap>
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={data} margin={{ top: 8, right: 8, bottom: 0, left: -6 }}>
            <CartesianGrid stroke="rgba(255,255,255,0.08)" vertical={false} />
            <XAxis
              dataKey="day"
              tickFormatter={fmt}
              tick={{ fill: "#93b8a2", fontSize: 10 }}
              stroke="rgba(255,255,255,0.08)"
              interval="preserveStartEnd"
            />
            <YAxis tick={{ fill: "#93b8a2", fontSize: 10 }} stroke="rgba(255,255,255,0.08)" width={30} domain={[0, yMax]} allowDecimals={false} />
            <Tooltip
              contentStyle={{ background: "rgba(11,11,12,0.94)", color: "#ffffff", border: "1px solid var(--border)", borderRadius: 10, fontSize: 12 }}
              labelFormatter={(d: any) => `${t("fc.day", { defaultValue: "Day" })} ${fmt(Number(d))}`}
              formatter={(val: any) =>
                Array.isArray(val)
                  ? [`${Math.round(val[0])}-${Math.round(val[1])}`, t("fc.band", { defaultValue: "90% band" })]
                  : [Math.round(val), t("fc.riskIndex", { defaultValue: "Risk index" })]
              }
            />
            <Area dataKey="band" stroke="none" fill="rgba(253,184,51,0.18)" isAnimationActive={false} />
            <Line dataKey="observed" stroke={OBSERVED} strokeWidth={2.4} dot={false} isAnimationActive={false} connectNulls={false} />
            <Line dataKey="forecast" stroke={FORECAST} strokeWidth={2.4} strokeDasharray="5 4" dot={false} isAnimationActive={false} connectNulls={false} />
            <ReferenceLine x={0} stroke="#16b65b" strokeDasharray="3 3" />
            <ReferenceLine x={Math.round(day)} stroke="#b3b6b1" />
            {peak !== 0 && <ReferenceDot x={peak} y={peakVal} r={4} fill="#e23b47" stroke="#fff" strokeWidth={1.5} />}
          </ComposedChart>
        </ResponsiveContainer>
      </Wrap>
      <Leg>
        <span><i style={{ borderColor: OBSERVED }} />{t("fc.observed", { defaultValue: "Observed" })}</span>
        <span><i style={{ borderColor: FORECAST, borderTopStyle: "dashed" }} />{t("fc.forecast", { defaultValue: "Forecast" })}</span>
        <span><i className="band" />{t("fc.band", { defaultValue: "90% band" })}</span>
      </Leg>
    </>
  );
};

export default ForecastChart;
