/**
 * MODELLED, deterministic metapopulation SEIR forecast over the Dubai site
 * graph (src/data/demo/sites.ts). Pure and typed so a real forecasting model
 * can replace the internals without touching any view.
 *
 * - Mobility: a gravity model (footfall / distance^2) plus a metro-corridor
 *   bonus couples the sites.
 * - Seasonality: November = start of flu/RSV season, so transmission ramps up
 *   across the window.
 * - Uncertainty: a 30-run ensemble with seeded parameter jitter -> median,
 *   p10-p90 band, and hotspot probability (share of runs crossing Elevated).
 * - Deterministic: seeded RNG, so the pitch never flickers.
 *
 * Day axis: index 0..28 maps to actual day -14..+14; NOW = index 14.
 */
import { SITES, METRO_RED, METRO_GREEN, Site } from "../data/demo/sites";
import { AREAS } from "../data/demo/areas";
import { mulberry32, jitter } from "../data/demo/seededRandom";

export const PAST_DAYS = 14;
export const FUTURE_DAYS = 14;
export const DAYS = PAST_DAYS + FUTURE_DAYS + 1; // 29
export const NOW_INDEX = PAST_DAYS; // 14
const ENSEMBLE = 30;
const SUBSTEPS = 2;
const DT = 0.5;

export type RiskTier = "low" | "moderate" | "elevated" | "high" | "critical";
export interface RiskTierMeta {
  key: RiskTier;
  color: string;
  min: number;
}
export const RISK_TIERS: RiskTierMeta[] = [
  { key: "low", color: "#fff3c4", min: 0 },
  { key: "moderate", color: "#fdb833", min: 0.03 },
  { key: "elevated", color: "#f3722c", min: 0.07 },
  { key: "high", color: "#c1121f", min: 0.13 },
  { key: "critical", color: "#5c0a1e", min: 0.22 },
];
export const RISK_TIER_MAP: Record<RiskTier, RiskTierMeta> = RISK_TIERS.reduce(
  (acc, t) => {
    acc[t.key] = t;
    return acc;
  },
  {} as Record<RiskTier, RiskTierMeta>,
);
export const tierForFraction = (v: number): RiskTier => {
  let tier: RiskTier = "low";
  for (const t of RISK_TIERS) if (v >= t.min) tier = t.key;
  return tier;
};

const N = SITES.length;
const IDX: Record<string, number> = {};
SITES.forEach((s, i) => (IDX[s.id] = i));

// ── mobility adjacency: gravity + metro corridor bonus ─────────────────────
const corridorPairs = new Set<string>();
[METRO_RED, METRO_GREEN].forEach((line) => {
  for (let k = 0; k < line.length - 1; k++) {
    corridorPairs.add(`${line[k]}|${line[k + 1]}`);
    corridorPairs.add(`${line[k + 1]}|${line[k]}`);
  }
});
const A: number[][] = SITES.map((si) => {
  const row = SITES.map((sj) => {
    if (si.id === sj.id) return 0;
    const d2 = (si.lat - sj.lat) ** 2 + (si.lon - sj.lon) ** 2 + 0.0004;
    let w = (si.footfall * sj.footfall) / d2;
    if (corridorPairs.has(`${si.id}|${sj.id}`)) w *= 3;
    return w;
  });
  const sum = row.reduce((a, b) => a + b, 0) || 1;
  return row.map((w) => w / sum);
});

// seasonal transmission multiplier across the window (flu/RSV season ramp)
const season = (dayIndex: number): number => 0.5 + 0.9 * (dayIndex / (DAYS - 1));

// ── run the ensemble once at module load ───────────────────────────────────
// runI[r][dayIndex][nodeIndex] = infected fraction
const runI: number[][][] = [];
for (let r = 0; r < ENSEMBLE; r++) {
  const rnd = mulberry32(r * 7919 + 12345);
  const beta0 = jitter(rnd, 0.58, 0.1);
  const coupling = jitter(rnd, 0.095, 0.04);
  const sigma = 1 / 3;
  const gamma = 1 / 5;
  const S = new Array(N);
  const E = new Array(N);
  const I = new Array(N);
  const R = new Array(N);
  for (let i = 0; i < N; i++) {
    const seed = Math.max(0, SITES[i].seed * jitter(rnd, 1, 0.25));
    I[i] = seed;
    E[i] = seed * 0.6;
    R[i] = 0;
    S[i] = Math.max(0, 1 - I[i] - E[i]);
  }
  const perDay: number[][] = [];
  for (let d = 0; d < DAYS; d++) {
    const betaT = beta0 * season(d);
    for (let s = 0; s < SUBSTEPS; s++) {
      const dS = new Array(N).fill(0);
      const dE = new Array(N).fill(0);
      const dI = new Array(N).fill(0);
      const dR = new Array(N).fill(0);
      for (let i = 0; i < N; i++) {
        let mix = I[i];
        const Ai = A[i];
        for (let j = 0; j < N; j++) if (Ai[j] > 0) mix += coupling * Ai[j] * I[j];
        const infect = betaT * S[i] * mix * DT;
        const e2i = sigma * E[i] * DT;
        const i2r = gamma * I[i] * DT;
        dS[i] = -infect;
        dE[i] = infect - e2i;
        dI[i] = e2i - i2r;
        dR[i] = i2r;
      }
      for (let i = 0; i < N; i++) {
        S[i] = Math.max(0, S[i] + dS[i]);
        E[i] = Math.max(0, E[i] + dE[i]);
        I[i] = Math.max(0, I[i] + dI[i]);
        R[i] = Math.max(0, R[i] + dR[i]);
      }
    }
    perDay.push(I.slice());
  }
  runI.push(perDay);
}

// ── percentiles per (day, node) ────────────────────────────────────────────
const pct = (sorted: number[], q: number): number =>
  sorted[Math.min(sorted.length - 1, Math.max(0, Math.round(q * (sorted.length - 1))))];

const medNode: number[][] = [];
const loNode: number[][] = [];
const hiNode: number[][] = [];
const probNode: number[][] = [];
for (let d = 0; d < DAYS; d++) {
  medNode.push(new Array(N));
  loNode.push(new Array(N));
  hiNode.push(new Array(N));
  probNode.push(new Array(N));
  const elevated = RISK_TIER_MAP.elevated.min;
  for (let i = 0; i < N; i++) {
    const vals = runI.map((run) => run[d][i]).sort((a, b) => a - b);
    medNode[d][i] = pct(vals, 0.5);
    loNode[d][i] = pct(vals, 0.1);
    hiNode[d][i] = pct(vals, 0.9);
    probNode[d][i] = vals.filter((v) => v >= elevated).length / vals.length;
  }
}

// city aggregate (footfall-weighted) per run per day
const totalFoot = SITES.reduce((a, s) => a + s.footfall, 0) || 1;
const cityMed: number[] = [];
const cityLo: number[] = [];
const cityHi: number[] = [];
for (let d = 0; d < DAYS; d++) {
  const perRun = runI
    .map((run) => {
      let acc = 0;
      for (let i = 0; i < N; i++) acc += SITES[i].footfall * run[d][i];
      return acc / totalFoot;
    })
    .sort((a, b) => a - b);
  cityMed.push(pct(perRun, 0.5));
  cityLo.push(pct(perRun, 0.1));
  cityHi.push(pct(perRun, 0.9));
}

// calibrate the displayed index against the ensemble: the hottest single site
// over the whole window maps to ~95, so values spread believably (never a wall
// of 100s). Tiers/colours are unaffected (they key off the raw fraction).
let _nodeMax = 0;
for (let d = 0; d < DAYS; d++)
  for (let i = 0; i < N; i++) if (medNode[d][i] > _nodeMax) _nodeMax = medNode[d][i];
let _cityMax = 0;
for (let d = 0; d < DAYS; d++) if (cityMed[d] > _cityMax) _cityMax = cityMed[d];

// ── public API ─────────────────────────────────────────────────────────────
export const dayToIndex = (day: number): number =>
  Math.max(0, Math.min(DAYS - 1, Math.round(day) + PAST_DAYS));
const interpAt = (arr: number[], day: number): number => {
  const x = Math.max(-PAST_DAYS, Math.min(FUTURE_DAYS, day)) + PAST_DAYS;
  const a = Math.floor(x);
  const b = Math.min(DAYS - 1, a + 1);
  const f = x - a;
  return arr[a] * (1 - f) + arr[b] * f;
};

export const nodeRiskAt = (nodeId: string, day: number): number => {
  const i = IDX[nodeId];
  if (i == null) return 0;
  return interpAt(medNode.map((r) => r[i]), day);
};
export const nodeBandAt = (nodeId: string, day: number): [number, number] => {
  const i = IDX[nodeId];
  if (i == null) return [0, 0];
  const di = dayToIndex(day);
  return [loNode[di][i], hiNode[di][i]];
};
export const hotspotProbability = (nodeId: string, day: number): number => {
  const i = IDX[nodeId];
  if (i == null) return 0;
  return Math.round(interpAt(probNode.map((r) => r[i]), day) * 100);
};

/**
 * Convert a modelled attack-rate fraction into a credible case count.
 *
 * The screening network covers a care-seeking respiratory cohort, NOT the whole
 * ~3.9M resident population, so projected and averted cases stay in a plausible
 * thousands-to-tens-of-thousands range over the forecast window. The per-cohort
 * attack rate is also capped (a single wave never infects everyone). Illustrative.
 */
export const MONITORED_POP = 85_000;
export const ATTACK_CAP = 0.45;
export const toCaseCount = (attackFraction: number): number =>
  Math.round(Math.min(ATTACK_CAP, Math.max(0, attackFraction)) * MONITORED_POP);
/** Cases avoided when attack rate drops from `hi` to `lo` (both capped). */
export const casesBetween = (hi: number, lo: number): number =>
  Math.max(0, toCaseCount(hi) - toCaseCount(lo));

export const INDEX_SCALE = _nodeMax > 0 ? 95 / _nodeMax : 900;
// the city is a footfall-weighted average, scaled so its peak reads ~70
const CITY_SCALE = _cityMax > 0 ? 70 / _cityMax : INDEX_SCALE;
export const cityRiskIndex = (day: number): number =>
  Math.min(100, interpAt(cityMed, day) * CITY_SCALE);
/** Raw city infected fraction (for tiering the city without a scale). */
export const cityRiskFraction = (day: number): number => interpAt(cityMed, day);
export const predictedSymptomaticRate = (day: number): number =>
  Math.round(interpAt(cityMed, day) * 90 * 10) / 10;
/** Number of AREAS (districts) whose hottest site is at Elevated tier or above. */
export const areasAtRisk = (day: number): number => {
  const di = dayToIndex(day);
  const elevated = RISK_TIER_MAP.elevated.min;
  let n = 0;
  for (const a of AREAS) {
    let risk = 0;
    a.siteIds.forEach((id) => {
      const i = IDX[id];
      if (i != null && medNode[di][i] > risk) risk = medNode[di][i];
    });
    if (risk >= elevated) n += 1;
  }
  return n;
};

export const districtsAtRisk = (day: number): number => {
  const di = dayToIndex(day);
  const kinds = new Set(["residential", "mall", "oldcity", "transit"]);
  let n = 0;
  for (let i = 0; i < N; i++) {
    if (kinds.has(SITES[i].type) && tierForFraction(medNode[di][i]) !== "low") {
      if (medNode[di][i] >= RISK_TIER_MAP.elevated.min) n += 1;
    }
  }
  return n;
};

export interface CurvePoint {
  day: number;
  observed: number | null;
  forecast: number | null;
  band: [number, number];
}
export const cityCurve = (): CurvePoint[] => {
  const out: CurvePoint[] = [];
  for (let d = 0; d < DAYS; d++) {
    const day = d - PAST_DAYS;
    const v = Math.min(100, cityMed[d] * CITY_SCALE);
    out.push({
      day,
      observed: day <= 0 ? v : null,
      forecast: day >= 0 ? v : null,
      band: [Math.min(100, cityLo[d] * CITY_SCALE), Math.min(100, cityHi[d] * CITY_SCALE)],
    });
  }
  return out;
};

export const peakDay = (): number => {
  let best = 0;
  let bestV = -1;
  for (let d = 0; d < DAYS; d++)
    if (cityMed[d] > bestV) {
      bestV = cityMed[d];
      best = d - PAST_DAYS;
    }
  return best;
};

export interface NodeCurvePoint {
  day: number;
  risk: number;
  lo: number;
  hi: number;
}
/** Per-node risk curve over the whole -14..+14 window (for drawers/sparklines). */
export const nodeCurve = (nodeId: string): NodeCurvePoint[] => {
  const i = IDX[nodeId];
  if (i == null) return [];
  const out: NodeCurvePoint[] = [];
  for (let d = 0; d < DAYS; d++) {
    out.push({ day: d - PAST_DAYS, risk: medNode[d][i], lo: loNode[d][i], hi: hiNode[d][i] });
  }
  return out;
};

export interface Hotspot {
  site: Site;
  risk: number;
  prob: number;
  tier: RiskTier;
  trend: 1 | 0 | -1;
}
export const topHotspots = (day: number, n = 6): Hotspot[] => {
  const di = dayToIndex(day);
  const diPrev = Math.max(0, di - 1);
  return SITES.map((s, i) => {
    const risk = medNode[di][i];
    const prev = medNode[diPrev][i];
    const trend: 1 | 0 | -1 = risk > prev * 1.02 ? 1 : risk < prev * 0.98 ? -1 : 0;
    return {
      site: s,
      risk,
      prob: Math.round(probNode[di][i] * 100),
      tier: tierForFraction(risk),
      trend,
    };
  })
    .filter((h) => h.site.type !== "kiosk")
    .sort((a, b) => b.risk - a.risk)
    .slice(0, n);
};

/**
 * Deterministic single-run city simulation with a transmission multiplier,
 * used for what-if scenarios/interventions. Returns the per-day risk-index
 * curve, the final attack rate (fraction ever infected) and the peak day index.
 */
export const simulateScenario = (
  betaMult: number,
): { index: number[]; attackRate: number; peakIndex: number } => {
  const rnd = mulberry32(42);
  const beta0 = jitter(rnd, 0.58, 0) * betaMult;
  const coupling = 0.095;
  const sigma = 1 / 3;
  const gamma = 1 / 5;
  const S = new Array(N);
  const E = new Array(N);
  const I = new Array(N);
  const R = new Array(N);
  for (let i = 0; i < N; i++) {
    I[i] = SITES[i].seed;
    E[i] = SITES[i].seed * 0.6;
    R[i] = 0;
    S[i] = Math.max(0, 1 - I[i] - E[i]);
  }
  const index: number[] = [];
  let peakIndex = 0;
  let peakV = -1;
  for (let d = 0; d < DAYS; d++) {
    const betaT = beta0 * season(d);
    for (let s = 0; s < SUBSTEPS; s++) {
      const dS = new Array(N).fill(0);
      const dE = new Array(N).fill(0);
      const dI = new Array(N).fill(0);
      const dR = new Array(N).fill(0);
      for (let i = 0; i < N; i++) {
        let mix = I[i];
        const Ai = A[i];
        for (let j = 0; j < N; j++) if (Ai[j] > 0) mix += coupling * Ai[j] * I[j];
        const infect = betaT * S[i] * mix * DT;
        const e2i = sigma * E[i] * DT;
        const i2r = gamma * I[i] * DT;
        dS[i] = -infect;
        dE[i] = infect - e2i;
        dI[i] = e2i - i2r;
        dR[i] = i2r;
      }
      for (let i = 0; i < N; i++) {
        S[i] = Math.max(0, S[i] + dS[i]);
        E[i] = Math.max(0, E[i] + dE[i]);
        I[i] = Math.max(0, I[i] + dI[i]);
        R[i] = Math.max(0, R[i] + dR[i]);
      }
    }
    let cityI = 0;
    for (let i = 0; i < N; i++) cityI += SITES[i].footfall * I[i];
    cityI /= totalFoot;
    index.push(Math.min(100, cityI * INDEX_SCALE));
    if (cityI > peakV) {
      peakV = cityI;
      peakIndex = d;
    }
  }
  let attack = 0;
  for (let i = 0; i < N; i++) attack += SITES[i].footfall * R[i];
  attack /= totalFoot;
  return { index, attackRate: attack, peakIndex };
};

/**
 * Shared engine internals, re-exported so the click-to-seed simulator
 * (src/model/simulator.ts) reuses the exact same mobility graph, seasonal
 * ramp and footfall weighting as the forecast - one physics, two surfaces.
 */
export const MOBILITY = A;
export const seasonAt = season;
export const TOTAL_FOOTFALL = totalFoot;
export const SITE_COUNT = N;

/** Heat points for the map: each site weighted by predicted risk at `day`. */
export const forecastHeatPoints = (day: number): Array<[number, number, number]> =>
  SITES.map((s) => [s.lat, s.lon, Math.min(1, nodeRiskAt(s.id, day) * 8)] as [number, number, number]).filter(
    (p) => p[2] > 0.02,
  );
