import React from "react";
import { IconType } from "react-icons";
import {
  TbPlane,
  TbBuildingStore,
  TbBuildingMosque,
  TbTrain,
  TbBuildingHospital,
  TbPlus,
  TbSchool,
  TbBuildingCommunity,
  TbStethoscope,
  TbBuildingSkyscraper,
  TbTent,
  TbMapPin,
} from "react-icons/tb";

const MAP: Record<string, IconType> = {
  gateway: TbPlane,
  mall: TbBuildingStore,
  oldcity: TbBuildingMosque,
  transit: TbTrain,
  hospital: TbBuildingHospital,
  clinic: TbPlus,
  pharmacy: TbPlus,
  education: TbSchool,
  residential: TbBuildingCommunity,
  hotel: TbBuildingSkyscraper,
  mosque: TbBuildingMosque,
  venue: TbTent,
  kiosk: TbStethoscope,
};

/** Crisp line icon for a site type (replaces the old emoji glyphs). */
const SiteIcon: React.FC<{ type: string; size?: number }> = ({ type, size = 16 }) => {
  const C = MAP[type] || TbMapPin;
  return <C size={size} />;
};

export default SiteIcon;
