/**
 * MODELLED click-to-seed outbreak simulator. The operator drops a seed anywhere
 * on the map; a deterministic metapopulation SEIR outbreak spreads forward from
 * that point over the Dubai site graph, reusing the exact mobility graph,
 * seasonal ramp and footfall weighting as the main forecast (src/model/forecast.ts).
 *
 * An optional containment zone (a circular cordon centred on the epicentre)
 * suppresses local transmission and cross-site mobility for every site inside it,
 * so the operator can watch cases averted in real time.
 *
 * Pure, deterministic (no RNG), so the pitch never flickers.
 */
import { SITES } from "../data/demo/sites";
import {
  MOBILITY,
  seasonAt,
  TOTAL_FOOTFALL,
  INDEX_SCALE,
  NOW_INDEX,
  toCaseCount,
  casesBetween,
} from "./forecast";

export const SIM_DAYS = 21; // forward horizon of a simulated outbreak
const SUBSTEPS = 2;
const DT = 0.5;
const BETA0 = 0.62;
const COUPLING = 0.35;
const SIGMA = 1 / 3;
const GAMMA = 1 / 5;

const SEED_SIGMA_KM = 2.2; // how tightly the seed concentrates on the epicentre
const SEED_PEAK = 0.03; // infected fraction injected at the epicentre site
const CONTAIN_LOCAL = 0.75; // local-transmission cut inside the cordon
const CONTAIN_MOBILITY = 0.7; // cross-site mobility cut touching the cordon

const N = SITES.length;

/** Great-circle distance in km. */
export const distKm = (aLat: number, aLon: number, bLat: number, bLon: number): number => {
  const R = 6371;
  const dLat = ((bLat - aLat) * Math.PI) / 180;
  const dLon = ((bLon - aLon) * Math.PI) / 180;
  const la1 = (aLat * Math.PI) / 180;
  const la2 = (bLat * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(la1) * Math.cos(la2) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
};

/** Nearest site to a point, by great-circle distance. */
export const nearestSite = (lat: number, lon: number): number => {
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < N; i++) {
    const d = distKm(lat, lon, SITES[i].lat, SITES[i].lon);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
};

export interface Containment {
  lat: number;
  lon: number;
  radiusKm: number;
}

export interface OutbreakResult {
  epicentreId: string;
  epicentreName: string;
  epicentreNameAr: string;
  perDayNode: number[][]; // [day 0..SIM_DAYS][nodeIndex] -> infected fraction
  cityIndex: number[]; // [day] -> 0..100 risk index
  peakIndex: number; // day index of city peak
  attackRate: number; // final fraction ever infected (footfall-weighted)
}

/**
 * Run a single deterministic SEIR outbreak from a seeded point, with an optional
 * containment cordon. Cheap (29 nodes x 21 days), safe to call per interaction.
 */
export const runOutbreak = (
  seed: { lat: number; lon: number },
  containment: Containment | null,
  responseDay: number = 0,
): OutbreakResult => {
  const epi = nearestSite(seed.lat, seed.lon);

  // which sites fall inside the cordon
  const contained = new Array<boolean>(N).fill(false);
  if (containment) {
    for (let i = 0; i < N; i++) {
      contained[i] =
        distKm(containment.lat, containment.lon, SITES[i].lat, SITES[i].lon) <=
        containment.radiusKm;
    }
  }

  // seed: a gaussian kernel over distance from the clicked point
  const S = new Array<number>(N);
  const E = new Array<number>(N);
  const I = new Array<number>(N);
  const R = new Array<number>(N);
  for (let i = 0; i < N; i++) {
    const d = distKm(seed.lat, seed.lon, SITES[i].lat, SITES[i].lon);
    const k = Math.exp(-(d * d) / (2 * SEED_SIGMA_KM * SEED_SIGMA_KM));
    I[i] = SEED_PEAK * k;
    E[i] = I[i] * 0.6;
    R[i] = 0;
    S[i] = Math.max(0, 1 - I[i] - E[i]);
  }

  const perDayNode: number[][] = [];
  const cityIndex: number[] = [];
  let peakIndex = 0;
  let peakV = -1;

  for (let d = 0; d <= SIM_DAYS; d++) {
    // the outbreak starts "now" and runs into deeper winter: ride the same ramp
    const betaT = BETA0 * seasonAt(Math.min(NOW_INDEX + d, 28));
    // containment only takes effect from the response day onward
    const cordonOn = d >= responseDay;
    for (let s = 0; s < SUBSTEPS; s++) {
      const dS = new Array<number>(N).fill(0);
      const dE = new Array<number>(N).fill(0);
      const dI = new Array<number>(N).fill(0);
      const dR = new Array<number>(N).fill(0);
      for (let i = 0; i < N; i++) {
        let mix = I[i];
        const Ai = MOBILITY[i];
        for (let j = 0; j < N; j++) {
          if (Ai[j] > 0) {
            let w = COUPLING * Ai[j];
            if (cordonOn && (contained[i] || contained[j])) w *= 1 - CONTAIN_MOBILITY;
            mix += w * I[j];
          }
        }
        const betaLocal = cordonOn && contained[i] ? betaT * (1 - CONTAIN_LOCAL) : betaT;
        const infect = betaLocal * S[i] * mix * DT;
        const e2i = SIGMA * E[i] * DT;
        const i2r = GAMMA * I[i] * DT;
        dS[i] = -infect;
        dE[i] = infect - e2i;
        dI[i] = e2i - i2r;
        dR[i] = i2r;
      }
      for (let i = 0; i < N; i++) {
        S[i] = Math.max(0, S[i] + dS[i]);
        E[i] = Math.max(0, E[i] + dE[i]);
        I[i] = Math.max(0, I[i] + dI[i]);
        R[i] = Math.max(0, R[i] + dR[i]);
      }
    }
    perDayNode.push(I.slice());
    let cityI = 0;
    for (let i = 0; i < N; i++) cityI += SITES[i].footfall * I[i];
    cityI /= TOTAL_FOOTFALL;
    const idx = Math.min(100, cityI * INDEX_SCALE);
    cityIndex.push(idx);
    if (cityI > peakV) {
      peakV = cityI;
      peakIndex = d;
    }
  }

  let attack = 0;
  for (let i = 0; i < N; i++) attack += SITES[i].footfall * R[i];
  attack /= TOTAL_FOOTFALL;

  return {
    epicentreId: SITES[epi].id,
    epicentreName: SITES[epi].name,
    epicentreNameAr: SITES[epi].nameAr,
    perDayNode,
    cityIndex,
    peakIndex,
    attackRate: attack,
  };
};

/** Infected fraction for a node, linearly interpolated at a fractional day. */
export const sampleNode = (result: OutbreakResult, nodeIndex: number, day: number): number => {
  const x = Math.max(0, Math.min(SIM_DAYS, day));
  const a = Math.floor(x);
  const b = Math.min(SIM_DAYS, a + 1);
  const f = x - a;
  return result.perDayNode[a][nodeIndex] * (1 - f) + result.perDayNode[b][nodeIndex] * f;
};

/** City risk index, interpolated at a fractional day. */
export const sampleCity = (result: OutbreakResult, day: number): number => {
  const x = Math.max(0, Math.min(SIM_DAYS, day));
  const a = Math.floor(x);
  const b = Math.min(SIM_DAYS, a + 1);
  const f = x - a;
  return result.cityIndex[a] * (1 - f) + result.cityIndex[b] * f;
};

/** Estimated cases over the horizon in the monitored cohort (capped attack rate). */
export const estimatedCases = (result: OutbreakResult): number =>
  toCaseCount(result.attackRate);

/** Cases averted by a containment run versus the uncontained baseline. */
export const casesAverted = (baseline: OutbreakResult, contained: OutbreakResult): number =>
  casesBetween(baseline.attackRate, contained.attackRate);

export interface Reach {
  id: string;
  name: string;
  nameAr: string;
  day: number;
}
/** Order in which sites are first "reached" (infected fraction crosses threshold). */
export const reachOrder = (result: OutbreakResult, threshold: number = 0.02): Reach[] => {
  const out: Reach[] = [];
  for (let i = 0; i < N; i++) {
    if (SITES[i].type === "kiosk") continue;
    for (let d = 0; d <= SIM_DAYS; d++) {
      if (result.perDayNode[d][i] >= threshold) {
        out.push({ id: SITES[i].id, name: SITES[i].name, nameAr: SITES[i].nameAr, day: d });
        break;
      }
    }
  }
  return out.sort((a, b) => a.day - b.day);
};
