interface HealthDataEntry {
	AgeGroup: string;
	longitude: number;
	latitude: number;
	Sex: string;
	DistanceMetric: number;
	Symptoms: string[];
}

// Privacy fix (X1): the public feed now sends aggregated grid cells, not raw
// per-person records. A cell is a rounded location plus a count of people
// (only cells with >= 5 people are sent).
interface GridCell {
	latitude: number;
	longitude: number;
	count: number;
}

export const filterHealthData = (
	healthData: HealthDataEntry[],
	selectedLocation: LocationKey,
	selectedSymptoms: string | string[]
): HealthDataEntry[] => {
	const locationBounds: Record<
		LocationKey,
		{ minLat: number; maxLat: number; minLng: number; maxLng: number }
	> = {
		dubai: { minLat: 24.8, maxLat: 25.6, minLng: 54.8, maxLng: 55.8 }
	};

	const bounds = locationBounds[selectedLocation];
	const normalizedSelectedSymptoms = (
		Array.isArray(selectedSymptoms)
			? selectedSymptoms
			: selectedSymptoms
				? [selectedSymptoms]
				: []
	).map((symptom) => symptom.toLowerCase());
	const hasAnySelectedSymptom = normalizedSelectedSymptoms.length > 0;

	return healthData.filter((entry) => {
		const matchesLocation =
			entry.latitude >= bounds.minLat &&
			entry.latitude <= bounds.maxLat &&
			entry.longitude >= bounds.minLng &&
			entry.longitude <= bounds.maxLng;

		const matchesSymptom =
			!hasAnySelectedSymptom ||
			normalizedSelectedSymptoms.includes("all") ||
			(entry.Symptoms || []).some((symptom) =>
				normalizedSelectedSymptoms.includes(symptom.toLowerCase())
			);

		return matchesLocation && matchesSymptom;
	});
};

// Illustrative per-symptom transmissibility factors - scale the modelled site
// risk so selecting a symptom shows which areas are at risk for THAT symptom.
const SYMPTOM_RISK: Record<string, number> = {
	covid: 1.4,
	sars: 1.6,
	influenza: 1.25,
	rsv: 1.15,
	cold: 0.85,
	heavysmoker: 0.65
};

// Public Virufy cough/disease-screening app the QR opens. Must match the URL
// encoded in the QR image (src/assets/images/disease-app-qr.png). Env-overridable.
const APP_URL =
	process.env.REACT_APP_APP_URL?.trim() || "https://virufy.org/disease-app";

// read the shareable URL hash once at module load so initial state is correct
// (avoids an async restore that would briefly land on the wrong page)
const HASH = (() => {
	try {
		return new URLSearchParams(
			(typeof window !== "undefined" ? window.location.hash : "").replace(/^#/, "")
		);
	} catch {
		return new URLSearchParams("");
	}
})();
const hget = (k: string): string | null => HASH.get(k);

const Dashboard: React.FC = () => {
	const [healthData, setHealthData] = useState<HealthDataEntry[]>([]);
	const [cellData, setCellData] = useState<GridCell[]>([]);
	const [selectedLocation, setSelectedLocation] =
		useState<LocationKey>("dubai");
	const [loadingSymptoms, setLoadingSymptoms] = useState(true);
	const [symptomsList, setSymptomsList] = useState<Symptom[]>([]);
	const [selectedSymptoms, setSelectedSymptoms] = useState<string[]>(() => {
		const sy = hget("sy");
		return sy ? sy.split(",").filter(Boolean) : [];
	});

	const ws = useRef<WebSocket | null>(null);
	const reconnectTimerRef = useRef<number | null>(null);
	const reconnectAttemptsRef = useRef(0);
	const isUnmountedRef = useRef(false);
	const [selectedLanguage, setSelectedLanguage] = useState<"en" | "ar" | "ja">(
		() => {
			const l = hget("l");
			return l === "ar" || l === "ja" ? l : "en";
		}
	);
	const [wsConnected, setWsConnected] = useState(false);
	const [railOpen, setRailOpen] = useState(true);
	const [now, setNow] = useState(() => Date.now());
	const [day, setDay] = useState(() => {
		const d = Number(hget("d"));
		return isNaN(d) ? 0 : Math.max(-14, Math.min(14, d));
	});
	const [playing, setPlaying] = useState(false);
	const [speed, setSpeed] = useState(1);
	const [railTab, setRailTab] = useState<
		"forecast" | "hotspots" | "nudges" | "plan"
	>(() => {
		const tb = hget("t");
		return tb === "hotspots" || tb === "nudges" || tb === "plan" ? tb : "forecast";
	});
	const [page, setPage] = useState<
		"overview" | "simulate" | "network" | "insights" | "summary"
	>(() => {
		const p = hget("pg");
		return p === "simulate" || p === "network" || p === "insights" || p === "summary"
			? p
			: "overview";
	});
	// ── click-to-seed outbreak simulator ──────────────────────────
	const [simMode, setSimMode] = useState(false);
	const [simSeed, setSimSeed] = useState<{ lat: number; lon: number } | null>(
		null
	);
	const [simDay, setSimDay] = useState(0);
	const [simPlaying, setSimPlaying] = useState(false);
	const [containOn, setContainOn] = useState(false);
	const [radiusKm, setRadiusKm] = useState(3);
	const [responseDay, setResponseDay] = useState(0);
	// ── site detail drawer + presentation ─────────────────────────
	const [detailId, setDetailId] = useState<string | null>(null);
	const [present, setPresent] = useState(false);
	const [copied, setCopied] = useState(false);
	const [qrOpen, setQrOpen] = useState(() => hget("qr") === "1");
	const [moreOpen, setMoreOpen] = useState(false);
	const headerCtlRef = useRef<HTMLDivElement>(null);
	const popLayerRef = useRef<HTMLDivElement>(null);
	const [appLoading, setAppLoading] = useState(true);
	const urlReadyRef = useRef(false);
	// default to the recommended plan so Plan figures are never 0 / +0d / 0% on load
	const [scenarioId, setScenarioId] = useState(() => hget("sc") || RECOMMENDED_SCENARIO);
	const [interventions, setInterventions] = useState<string[]>(() => {
		const iv = hget("iv");
		return iv ? iv.split(",").filter(Boolean) : [...RECOMMENDED_INTERVENTIONS];
	});
	const toggleIntervention = useCallback((id: string) => {
		setInterventions((prev) =>
			prev.indexOf(id) >= 0 ? prev.filter((x) => x !== id) : [...prev, id]
		);
	}, []);
	const [focusSite, setFocusSite] = useState<{
		lat: number;
		lon: number;
		zoom?: number;
	} | null>(null);
	const [selectedArea, setSelectedArea] = useState<string | null>(null);
	const [conditions, setConditions] = useState<Conditions | null>(null);

	const { t, i18n } = useTranslation();

	const filteredHealthData = filterHealthData(
		healthData,
		selectedLocation,
		selectedSymptoms
	);
	// ── pitch KPIs: total screenings = sum of aggregated cell counts ──
	const totalScreenings = cellData.reduce((sum, c) => sum + (c.count || 0), 0);
	// ── symptom lens: scale modelled risk by the selected symptom(s) ──
	const symptomActive = selectedSymptoms.length > 0;
	const symFactor = symptomActive
		? Math.max.apply(
				null,
				selectedSymptoms.map((id) => SYMPTOM_RISK[id] || 1)
			)
		: 1;
	// ── forecast-derived values at the current timeline day ───────
	const forecastSites = SITES.map((s) => {
		const base = nodeRiskAt(s.id, day);
		const risk = symptomActive ? Math.min(0.45, base * symFactor) : base;
		const tier = tierForFraction(risk);
		return {
			id: s.id,
			name: s.name,
			nameAr: s.nameAr,
			lat: s.lat,
			lon: s.lon,
			color: RISK_TIER_MAP[tier].color,
			tier,
			prob: hotspotProbability(s.id, day),
			risk,
			index: Math.round(Math.min(100, risk * INDEX_SCALE)),
			atRisk: symptomActive ? risk >= RISK_TIER_MAP.elevated.min : false,
			icon: SITE_ICON[s.type],
			type: s.type,
			footfall: s.footfall
		};
	});
	// aggregate each major area from its member sites (max risk)
	const siteRiskById: Record<string, number> = {};
	forecastSites.forEach((s) => {
		siteRiskById[s.id] = s.risk;
	});
	const forecastAreas = AREAS.map((a) => {
		let risk = 0;
		a.siteIds.forEach((id) => {
			const r = siteRiskById[id] || 0;
			if (r > risk) risk = r;
		});
		const tier = tierForFraction(risk);
		return {
			id: a.id,
			name: a.name,
			nameAr: a.nameAr,
			lat: a.lat,
			lon: a.lon,
			color: RISK_TIER_MAP[tier].color,
			risk,
			index: Math.round(Math.min(100, risk * INDEX_SCALE)),
			status: t(`fc.tier.${tier}`, { defaultValue: tier }),
			siteIds: a.siteIds
		};
	});
	const handleAreaClick = useCallback((id: string) => {
		const a = AREAS.find((x) => x.id === id);
		if (!a) return;
		setSelectedArea(id);
		setFocusSite({ lat: a.lat, lon: a.lon, zoom: a.zoom });
	}, []);
	const clearArea = useCallback(() => {
		setSelectedArea(null);
		setDetailId(null);
		setFocusSite({
			lat: LOCATIONS.dubai.lat,
			lon: LOCATIONS.dubai.lon,
			zoom: LOCATIONS.dubai.zoom
		});
	}, []);
	// spread-animation flows along the metro corridors, scaled by transmission
	const corridorFlows = [METRO_RED, METRO_GREEN].flatMap((line) =>
		line.slice(0, -1).map((id, k) => {
			const a = SITE_MAP[id];
			const b = SITE_MAP[line[k + 1]];
			const ra = nodeRiskAt(a.id, day);
			const rb = nodeRiskAt(b.id, day);
			const tier = tierForFraction(Math.max(ra, rb));
			return {
				from: [a.lon, a.lat] as [number, number],
				to: [b.lon, b.lat] as [number, number],
				intensity: Math.min(1, ((ra + rb) / 2) * 10),
				color: RISK_TIER_MAP[tier].color
			};
		})
	);
	// one shared KPI selector so Map / Summary / Insights never diverge
	const kpis = useMemo(() => deriveKpis(totalScreenings, day), [totalScreenings, day]);
	const cityTier = tierForFraction(cityRiskFraction(day));
	const cityTierColor = RISK_TIER_MAP[cityTier].color;
	// KPI sparkline series (forecast-driven, -14..+14)
	const cityCurveArr = cityCurve();
	const cityIdxSeries = cityCurveArr.map((p) =>
		Math.round((p.observed != null ? p.observed : p.forecast || 0) as number)
	);
	const plan = computePlan(scenarioId, interventions);
	const peak = peakDay();
	const peakDateLong = new Date(Date.now() + peak * 86400000).toLocaleDateString(
		"en-GB",
		{ timeZone: "Asia/Dubai", weekday: "short", day: "numeric", month: "short" }
	);
	const statusDate = new Date(now).toLocaleDateString("en-GB", {
		timeZone: "Asia/Dubai",
		weekday: "short",
		day: "numeric",
		month: "short"
	});

	// ── outbreak simulator: deterministic SEIR re-run from the seed ───
	const baselineRun = useMemo(
		() => (simSeed ? runOutbreak(simSeed, null) : null),
		[simSeed]
	);
	const containedRun = useMemo(
		() =>
			simSeed && containOn
				? runOutbreak(
						simSeed,
						{ lat: simSeed.lat, lon: simSeed.lon, radiusKm },
						responseDay
					)
				: null,
		[simSeed, containOn, radiusKm, responseDay]
	);
	// reference run: same cordon but acting immediately (day 0) - for cost-of-delay
	const containedNow = useMemo(
		() =>
			simSeed && containOn
				? runOutbreak(simSeed, { lat: simSeed.lat, lon: simSeed.lon, radiusKm }, 0)
				: null,
		[simSeed, containOn, radiusKm]
	);
	const containmentObj =
		simSeed && containOn
			? { lat: simSeed.lat, lon: simSeed.lon, radiusKm }
			: null;
	const activeRun = containOn && containedRun ? containedRun : baselineRun;
	const avertedNow =
		baselineRun && containedNow ? casesAverted(baselineRun, containedNow) : 0;
	const simReach = activeRun
		? reachOrder(activeRun).find((r) => r.day > simDay + 0.001) || null
		: null;
	const simHeat = activeRun
		? SITES.map((s, i) => ({
				lat: s.lat,
				lon: s.lon,
				w: sampleNode(activeRun, i, simDay)
			}))
		: [];

	const handleSeed = useCallback((lat: number, lon: number) => {
		setSimSeed({ lat, lon });
		setSimDay(0);
		setSimPlaying(false);
		setSimMode(false);
		setRailOpen(true);
		setRailTab("simulate");
	}, []);
	const toggleSimMode = useCallback(() => {
		setSimMode((v) => {
			const next = !v;
			if (next) {
				setRailOpen(true);
				setRailTab("simulate");
			}
			return next;
		});
	}, []);
	const clearSim = useCallback(() => {
		setSimSeed(null);
		setSimMode(false);
		setContainOn(false);
		setSimDay(0);
		setSimPlaying(false);
		setResponseDay(0);
	}, []);

	// site detail drawer
	const detailSite = detailId ? SITE_MAP[detailId] : null;
	const detailCurve = detailId ? nodeCurve(detailId) : [];
	const handleSiteClick = useCallback((id: string) => setDetailId(id), []);

	const connectWebSocket = useCallback(() => {
		const websocketURL = process.env.REACT_APP_WEBSOCKET_URL?.trim();

		if (!websocketURL) {
			console.warn("WebSocket URL is not configured. Skipping connection.");
			return;
		}

		try {
			new URL(websocketURL);
		} catch {
			console.error("Invalid WebSocket URL:", websocketURL);
			return;
		}

		if (ws.current && ws.current.readyState === WebSocket.OPEN) {
			return;
		}

		if (ws.current && ws.current.readyState === WebSocket.CONNECTING) {
			return;
		}

		ws.current = new WebSocket(websocketURL);

		ws.current.onopen = () => {
			console.log("WebSocket connection opened");
			reconnectAttemptsRef.current = 0;
			setWsConnected(true);
			ws.current?.send(JSON.stringify({ action: "send_initial_data" }));
		};

		ws.current.onmessage = (event) => {
			try {
				const data = JSON.parse(event.data);
				if (data.message === "connected" || data.message === "pong") {
					console.log("WebSocket control message:", data.message);
				} else if (data.type === "cells" && Array.isArray(data.cells)) {
					// Aggregated initial payload (privacy fix X1): replace the full
					// set of grid cells. No per-person location/age/sex is sent.
					setCellData(data.cells as GridCell[]);
				} else if (data.type === "cell" && data.cell) {
					// Single aggregated cell update: upsert by rounded lat/lng.
					const cell = data.cell as GridCell;
					setCellData((prev) => {
						const keyOf = (c: GridCell) => `${c.latitude},${c.longitude}`;
						const next = prev.filter((c) => keyOf(c) !== keyOf(cell));
						next.push(cell);
						return next;
					});
				} else if (data.Symptoms) {
					// Legacy per-person record (pre-X1 Lambda). The current Lambda no
					// longer sends these; kept only for backward compatibility.
					setHealthData((prevData) => [...prevData, data as HealthDataEntry]);
				}
			} catch (parseError) {
				console.error("Invalid WebSocket message payload:", parseError);
			}
		};

		ws.current.onclose = (event) => {
			setWsConnected(false);
			if (isUnmountedRef.current) {
				return;
			}

			if (shouldReconnectOnClose(event.code)) {
				const delay = getReconnectDelay(reconnectAttemptsRef.current);
				reconnectAttemptsRef.current += 1;
				console.warn(
					`WebSocket closed unexpectedly (code ${event.code}). Reconnecting in ${delay}ms...`
				);
				if (reconnectTimerRef.current) {
					window.clearTimeout(reconnectTimerRef.current);
				}
				reconnectTimerRef.current = window.setTimeout(() => {
					connectWebSocket();
				}, delay);
				return;
			}

			console.log("WebSocket connection closed normally", event.code);
		};

		ws.current.onerror = (error) => {
			console.error("WebSocket error:", error);
			setWsConnected(false);
		};
	}, []);

	// Gulf Standard Time clock in the header
	useEffect(() => {
		const id = window.setInterval(() => setNow(Date.now()), 1000);
		return () => window.clearInterval(id);
	}, []);

	// live Dubai conditions (real, Open-Meteo); refresh every 10 minutes
	useEffect(() => {
		let alive = true;
		const load = () => {
			fetchConditions().then((c) => {
				if (alive) setConditions(c);
			});
		};
		load();
		const id = window.setInterval(load, 10 * 60 * 1000);
		return () => {
			alive = false;
			window.clearInterval(id);
		};
	}, []);

	// state is initialised from the URL hash (see useState initialisers above);
	// here we just apply the restored language and arm the URL-sync effect.
	useEffect(() => {
		if (selectedLanguage !== "en") i18n.changeLanguage(selectedLanguage);
		urlReadyRef.current = true;
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, []);

	// ── keep the URL hash in sync so the view is always shareable ─────
	useEffect(() => {
		if (!urlReadyRef.current) return;
		const p = new URLSearchParams();
		p.set("d", String(day));
		p.set("pg", page);
		p.set("l", selectedLanguage);
		p.set("t", railTab);
		p.set("sc", scenarioId);
		if (interventions.length) p.set("iv", interventions.join(","));
		if (selectedSymptoms.length) p.set("sy", selectedSymptoms.join(","));
		window.history.replaceState(null, "", "#" + p.toString());
	}, [
		day,
		page,
		selectedLanguage,
		railTab,
		scenarioId,
		interventions,
		selectedSymptoms
	]);

	const handleShare = useCallback(() => {
		const url = window.location.href;
		const done = () => {
			setCopied(true);
			window.setTimeout(() => setCopied(false), 2000);
		};
		if (navigator.clipboard && navigator.clipboard.writeText) {
			navigator.clipboard.writeText(url).then(done).catch(done);
		} else {
			done();
		}
	}, []);

	useEffect(() => {
		isUnmountedRef.current = false;
		connectWebSocket();

		const pingInterval = window.setInterval(
			() => {
				if (ws.current?.readyState === WebSocket.OPEN) {
					ws.current.send(JSON.stringify({ action: "ping", message: "ping" }));
				}
			},
			5 * 60 * 1000
		);

		return () => {
			isUnmountedRef.current = true;
			window.clearInterval(pingInterval);
			if (reconnectTimerRef.current) {
				window.clearTimeout(reconnectTimerRef.current);
			}
			if (ws.current && ws.current.readyState === WebSocket.OPEN) {
				ws.current.close(1000, "Component unmounting");
			}
		};
	}, [connectWebSocket]);

	useEffect(() => {
		const loadSymptoms = async () => {
			try {
				const rawSymptoms = (await fetchSymptoms()) || [];
				const symptoms = Array.isArray(rawSymptoms) ? rawSymptoms : [];
				const withoutAll = symptoms.filter((s) => s.id !== "All");
				const fullList = [{ id: "All", label: "All" }, ...withoutAll];
				setSymptomsList(fullList);
				setSelectedSymptoms([]);
			} catch (error) {
				console.error("Failed to load symptoms", error);
			} finally {
				setLoadingSymptoms(false);
			}
		};
		loadSymptoms();
	}, []);

	const handleLanguageChange = useCallback(
		(language: "en" | "ar" | "ja") => {
			setSelectedLanguage(language);
			i18n.changeLanguage(language);
		},
		[i18n]
	);

	const startPresent = useCallback(() => {
		setPresent(true);
		setPage("overview");
		setDay(0);
		setPlaying(true);
		setQrOpen(false);
	}, []);
	const exitPresent = useCallback(() => {
		setPresent(false);
		setPlaying(false);
	}, []);

	// branded loading splash on first load
	useEffect(() => {
		const id = window.setTimeout(() => setAppLoading(false), 1500);
		return () => window.clearTimeout(id);
	}, []);

	// close header popovers (overflow menu / QR) on outside click or Escape
	useEffect(() => {
		if (!moreOpen && !qrOpen) return;
		const onDoc = (e: MouseEvent) => {
			const t = e.target as Node;
			const inBtn = headerCtlRef.current && headerCtlRef.current.contains(t);
			const inPop = popLayerRef.current && popLayerRef.current.contains(t);
			if (!inBtn && !inPop) {
				setMoreOpen(false);
				setQrOpen(false);
			}
		};
		const onKey = (e: KeyboardEvent) => {
			if (e.key === "Escape") {
				setMoreOpen(false);
				setQrOpen(false);
			}
		};
		document.addEventListener("mousedown", onDoc);
		document.addEventListener("keydown", onKey);
		return () => {
			document.removeEventListener("mousedown", onDoc);
			document.removeEventListener("keydown", onKey);
		};
	}, [moreOpen, qrOpen]);

	const toggleSymptom = useCallback((symptomId: string) => {
		setSelectedSymptoms((prevSelected) => {
			if (symptomId === "All") {
				return [];
			}

			const nextSelected = prevSelected.filter((id) => id !== "All");
			return nextSelected.includes(symptomId)
				? nextSelected.filter((id) => id !== symptomId)
				: [...nextSelected, symptomId];
		});
	}, []);

	const isRTL = i18n.language === "ar";
	const gst = new Date(now).toLocaleTimeString("en-GB", {
		timeZone: "Asia/Dubai",
		hour: "2-digit",
		minute: "2-digit",
		second: "2-digit"
	});
	// written, model-driven headline for the floating panel
	const _tops = topHotspots(day, 2).map((h) =>
		i18n.language === "ar" ? h.site.nameAr : h.site.name
	);
	const railHeadline =
		_tops.length >= 2
			? t("rail.headline", {
					a: _tops[0],
					b: _tops[1],
					d: peakDateLong,
					defaultValue: "{{a}} and {{b}} lead the rise; city peak expected {{d}}"
				})
			: t("rail.headlineOne", {
					d: peakDateLong,
					defaultValue: "City peak expected {{d}}"
				});
	const cityTierLabel = t(`fc.tier.${cityTier}`, { defaultValue: cityTier });

	return (
		<AppShell dir={isRTL ? "rtl" : "ltr"}>
			<Splash $hide={!appLoading} aria-hidden={!appLoading}>
				<div className="in">
					<BrandMark size={58} />
					<div className="nm">{t("dashboard.appTitle")}</div>
					<div className="sub">{t("dashboard.brandSub")}</div>
					<div className="bar"><i /></div>
				</div>
			</Splash>
			{present && (
				<PresentExit onClick={exitPresent}>
					<FiX size={14} /> {t("present.exit", { defaultValue: "Exit presentation" })}
				</PresentExit>
			)}

			<Main>
				<HeaderBar>
					<Brand>
						<BrandMark size={28} />
						<span className="brandname display">Dubai Respiratory Early Warning</span>
					</Brand>
					<NavGroup role="tablist">
						<NavTab $active={page === "overview"} onClick={() => setPage("overview")}><FiMap size={14} />{t("nav.overview", { defaultValue: "Map" })}</NavTab>
						<NavTab $active={page === "simulate"} onClick={() => setPage("simulate")}><FiCrosshair size={14} />{t("nav.simulate", { defaultValue: "Simulate" })}</NavTab>
						<NavTab $active={page === "network"} onClick={() => setPage("network")}><FiShare2 size={14} />{t("nav.network", { defaultValue: "Network" })}</NavTab>
						<NavTab $active={page === "insights"} onClick={() => setPage("insights")}><FiBarChart2 size={14} />{t("nav.insights", { defaultValue: "Insights" })}</NavTab>
						<NavTab $active={page === "summary"} onClick={() => setPage("summary")}><FiFileText size={14} />{t("nav.summary", { defaultValue: "Summary" })}</NavTab>
					</NavGroup>
					<div style={{ flex: 1 }} />
					<DataStatus><i />{t("appbar.dataStatus", { defaultValue: "Demo data, live screening feed" })}</DataStatus>
					<LangSeg role="group" aria-label={t("menu.language", { defaultValue: "Language" })}>
						<LangSegBtn $active={selectedLanguage === "en"} onClick={() => handleLanguageChange("en")}>EN</LangSegBtn>
						<LangSegBtn $active={selectedLanguage === "ar"} onClick={() => handleLanguageChange("ar")}>العربية</LangSegBtn>
						<LangSegBtn $active={selectedLanguage === "ja"} onClick={() => handleLanguageChange("ja")}>日本語</LangSegBtn>
					</LangSeg>
					<HeaderCtl ref={headerCtlRef}>
						<IconBtn $active={moreOpen} onClick={() => { setMoreOpen((v) => !v); setQrOpen(false); }} aria-label={t("appbar.more", { defaultValue: "More" })}>⋯</IconBtn>
						</HeaderCtl>
					<HeaderBtn $accent onClick={startPresent}>{t("present.btn", { defaultValue: "Present" })}</HeaderBtn>
				</HeaderBar>

				{(page === "overview" || page === "simulate") && (
					<Stage>
						<MapPane>
							<MapComponent
								lat={LOCATIONS[selectedLocation].lat}
								lon={LOCATIONS[selectedLocation].lon}
								zoom={LOCATIONS[selectedLocation].zoom}
								lang={i18n.language}
								focus={focusSite}
								sites={forecastSites}
								flows={simSeed ? [] : corridorFlows}
								simMode={simMode}
								simActive={!!simSeed}
								onSeed={handleSeed}
								simSeed={simSeed}
								simDay={simDay}
								simHeat={simHeat}
								containment={containmentObj}
								onSiteClick={handleSiteClick}
								symptomActive={symptomActive}
								areas={page === "overview" && !simSeed ? forecastAreas : []}
								selectedArea={page === "overview" && !simSeed ? selectedArea : null}
								onAreaClick={handleAreaClick}
								points={cellData.map((cell) => ({ lat: cell.latitude, lng: cell.longitude, intensity: cell.count }))}
							/>
						</MapPane>

						{page === "overview" && (
							<StatusPill>
								<span className="live"><i />{wsConnected ? t("dashboard.live") : t("dashboard.offline")}</span>
								<span className="sep" aria-hidden="true" />
								<span>{statusDate} <b>{gst}</b> GST</span>
								<span className="sep" aria-hidden="true" />
								<span><b>{conditions && conditions.tempC != null ? `${Math.round(conditions.tempC)}°` : "n/a"}</b></span>
								<span><b>{conditions && conditions.humidity != null ? `${Math.round(conditions.humidity)}%` : "n/a"}</b></span>
								<span>PM10 <b>{conditions && conditions.pm10 != null ? Math.round(conditions.pm10) : "n/a"}</b></span>
								<span className="sep" aria-hidden="true" />
								<span>{t("exec.risk", { defaultValue: "Risk" })}: <b style={{ color: cityTierColor }}>{cityTierLabel}</b></span>
								<span className="demo">{t("dashboard.demoPill")}</span>
							</StatusPill>
						)}

						{page === "overview" && (
							<LensCard>
								<div className="eyebrow">{t("lens.title", { defaultValue: "Lens" })}</div>
								<FilterLabel>{t("dashboard.location")}</FilterLabel>
								<ChipRow>
									{(Object.keys(LOCATIONS) as LocationKey[]).map((key) => (
										<Chip key={key} $active={selectedLocation === key} onClick={() => setSelectedLocation(key)}>{t(`dashboard.locations.${key}`)}</Chip>
									))}
								</ChipRow>
								<FilterLabel style={{ marginTop: 11, display: "block" }}>{t("dashboard.symptomsLabel")}</FilterLabel>
								{loadingSymptoms ? (
									<div style={{ color: "var(--muted)", fontSize: 12 }}>{t("dashboard.loadingSymptoms")}</div>
								) : (
									<ChipRow>
										{symptomsList.map((symptom) => {
											const isSelected = symptom.id === "All" ? selectedSymptoms.length === 0 : selectedSymptoms.includes(symptom.id);
											return (
												<Chip key={symptom.id} $active={isSelected} onClick={() => toggleSymptom(symptom.id)}>{symptom.id === "All" ? "All" : t(`symptoms.${symptom.id}`)}</Chip>
											);
										})}
									</ChipRow>
								)}
							</LensCard>
						)}

						<Legend>
							<div className="t">{t("dashboard.legendTitle")}</div>
							<div className="ramp" />
							<div className="ends">
								<span>{t("dashboard.legendLow")}</span>
								<span>{t("dashboard.legendHigh")}</span>
							</div>
							<div className="prov">
								<span><i style={{ background: "var(--prov-real)" }} />{t("prov.real")}</span>
								<span><i style={{ background: "var(--prov-modelled)" }} />{t("prov.modelled")}</span>
								<span><i style={{ background: "var(--prov-illustrative)" }} />{t("prov.illustrative")}</span>
								<span><i style={{ background: "var(--prov-pending)" }} />{t("prov.pending")}</span>
							</div>
						</Legend>
						{detailSite && (
							<NodeDrawer site={detailSite} curve={detailCurve} day={day} lang={i18n.language} onClose={() => setDetailId(null)} />
						)}
						{page === "overview" && selectedArea && (
							<BackChip onClick={clearArea}>
								← <span>{t("map.allDubai", { defaultValue: "All Dubai" })}</span>
								<span className="sep">›</span>
								<b>{i18n.language === "ar" ? (AREAS.find((x) => x.id === selectedArea) || { nameAr: "" }).nameAr : (AREAS.find((x) => x.id === selectedArea) || { name: "" }).name}</b>
							</BackChip>
						)}
						{page === "overview" && (
							<SimToggle $on={false} onClick={() => { setPage("simulate"); setSimMode(true); setRailOpen(true); }}>
								<FiCrosshair size={14} /> {t("sim.toggleOff", { defaultValue: "Run an outbreak what-if" })}
							</SimToggle>
						)}
						<RailToggle $open={railOpen} onClick={() => setRailOpen((v) => !v)} aria-label={t("dashboard.toggleRail")}>
							{railOpen ? (isRTL ? "›" : "‹") : isRTL ? "‹" : "›"}
						</RailToggle>
						<RightRail $open={railOpen}>
							<RailInner>
								<RailHead>
									{page === "overview" ? (
										<>
											<div className="eyebrow">{t("rail.eyebrow", { defaultValue: "This week in Dubai" })}</div>
											<div className="headline">{railHeadline}</div>
										</>
									) : (
										<span className="ttl">{t("sim.panelTitle", { defaultValue: "What if an outbreak starts here?" })}</span>
									)}
								</RailHead>
								{page === "overview" ? (
									<>
										<KpiRow>
											<KpiMini><div className="l">{t("dashboard.kpi.screenings")}</div><div className="v">{kpis.screenings.toLocaleString()}</div></KpiMini>
											<KpiMini><div className="l">{t("dashboard.kpi.symptomatic")}</div><div className="v">{kpis.symptomatic}%</div></KpiMini>
											<KpiMini><div className="l">{t("dashboard.kpi.hotspots")}</div><div className="v">{kpis.districts}</div></KpiMini>
											<KpiMini><div className="l">{t("dashboard.kpi.peak")}</div><div className="v">{kpis.peak === 0 ? t("fc.today", { defaultValue: "Today" }) : `+${kpis.peak}d`}</div></KpiMini>
										</KpiRow>
										<RailTabs role="tablist">
											<RailTab $active={railTab === "forecast"} onClick={() => setRailTab("forecast")}>{t("rail.forecast", { defaultValue: "Forecast" })}</RailTab>
											<RailTab $active={railTab === "hotspots"} onClick={() => setRailTab("hotspots")}>{t("rail.hotspots", { defaultValue: "Hotspots" })}</RailTab>
											<RailTab $active={railTab === "nudges"} onClick={() => setRailTab("nudges")}>{t("rail.nudges", { defaultValue: "Actions" })}</RailTab>
											<RailTab $active={railTab === "plan"} onClick={() => setRailTab("plan")}>{t("rail.plan", { defaultValue: "Plan" })}</RailTab>
										</RailTabs>
										<RailBody>
											{railTab === "forecast" && <ForecastChart day={day} />}
											{railTab === "hotspots" && (
												<Hotspots day={day} lang={i18n.language} onSelect={(h) => setFocusSite({ lat: h.site.lat, lon: h.site.lon })} />
											)}
											{railTab === "nudges" && (
												<Nudges day={day} lang={i18n.language} onSelect={(n) => { setPlaying(false); setDay(n.day); const s = SITE_MAP[n.targetId]; if (s) setFocusSite({ lat: s.lat, lon: s.lon }); }} />
											)}
											{railTab === "plan" && (
												<Plan scenarioId={scenarioId} setScenarioId={setScenarioId} interventions={interventions} toggleIntervention={toggleIntervention} plan={plan} lang={i18n.language} />
											)}
										</RailBody>
									</>
								) : (
									<RailBody>
										<Simulator simMode={simMode} onToggleMode={toggleSimMode} baseline={baselineRun} contained={containedRun} simDay={simDay} setSimDay={setSimDay} simPlaying={simPlaying} setSimPlaying={setSimPlaying} containOn={containOn} setContainOn={setContainOn} radiusKm={radiusKm} setRadiusKm={setRadiusKm} responseDay={responseDay} setResponseDay={setResponseDay} avertedNow={avertedNow} nextReach={simReach} onClear={clearSim} lang={i18n.language} seed={simSeed} onSeedAt={handleSeed} />
									</RailBody>
								)}
							</RailInner>
						</RightRail>

						{page === "overview" && (
							<Timeline day={day} setDay={setDay} playing={playing} setPlaying={setPlaying} speed={speed} setSpeed={setSpeed} peak={peak} rtl={isRTL} now={now} series={cityIdxSeries} />
						)}
					</Stage>
				)}

				{page === "network" && (
					<PageWrap>
						<PageHead>
							<div className="eyebrow">{t("nav.network", { defaultValue: "Network" })}</div>
							<div className="h">{t("network.title", { defaultValue: "Mobility network" })}</div>
							<div className="s">{t("network.sub", { defaultValue: "How the forecast moves between Dubai sites. Tap a node to inspect it on the map." })}</div>
						</PageHead>
						<PanelCard style={{ maxWidth: 1100, margin: "0 auto" }}>
							<NetworkGraph day={day} lang={i18n.language} onSelect={(id) => { setDetailId(id); const s = SITE_MAP[id]; if (s) setFocusSite({ lat: s.lat, lon: s.lon }); setPage("overview"); }} />
						</PanelCard>
					</PageWrap>
				)}

				{page === "insights" && (
					<InsightsPage
						lang={i18n.language}
						day={day}
						realScreenings={totalScreenings}
						healthData={filteredHealthData}
						scenarioId={scenarioId}
						setScenarioId={setScenarioId}
						interventions={interventions}
						toggleIntervention={toggleIntervention}
						plan={plan}
						onHotspotSelect={(h) => { setFocusSite({ lat: h.site.lat, lon: h.site.lon }); setPage("overview"); }}
					/>
				)}

				{page === "summary" && (
					<SummaryPage
						lang={i18n.language}
						now={now}
						kpis={kpis}
						onNavigate={(pg) => setPage(pg)}
					/>
				)}
			</Main>

			{(moreOpen || qrOpen) && (
				<HeaderPopLayer ref={popLayerRef}>
					{moreOpen && (
						<HeaderPop>
							<HeaderPopItem onClick={() => { setQrOpen(true); setMoreOpen(false); }}><FiGrid size={14} /> {t("qr.btn", { defaultValue: "App QR" })}</HeaderPopItem>
							<HeaderPopItem onClick={() => { handleShare(); setMoreOpen(false); }}><FiShare2 size={14} /> {copied ? t("share.copied", { defaultValue: "Link copied" }) : t("share.btn", { defaultValue: "Share" })}</HeaderPopItem>
						</HeaderPop>
					)}
					{qrOpen && (
						<QRPanel>
							<a href={APP_URL} target="_blank" rel="noopener noreferrer"><img src={qrSrc} alt={t("qr.cap", { defaultValue: "Scan to record a cough on the Virufy app" })} /></a>
							<div className="cap">{t("qr.cap", { defaultValue: "Scan to record a cough on the Virufy app" })}</div>
						</QRPanel>
					)}
				</HeaderPopLayer>
			)}
		</AppShell>
	);
};

export default Dashboard;
