/**
 * Deterministic PRNG (mulberry32). Every demo/model value is seeded so the
 * pitch never flickers: the same seed always yields the same sequence.
 */
export const mulberry32 = (seed: number): (() => number) => {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

/** Gaussian-ish jitter in [centre-spread, centre+spread] from a unit sample. */
export const jitter = (rnd: () => number, centre: number, spread: number): number =>
  centre + (rnd() - 0.5) * 2 * spread;
