import React, { useCallback, useEffect, useRef } from "react";
import * as maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";

export interface SiteFeature {
  id: string;
  name: string;
  nameAr: string;
  lat: number;
  lon: number;
  color: string;
  tier: string;
  prob: number;
  risk: number;
  index: number;
  icon: string;
  type: string;
  footfall: number;
  atRisk?: boolean;
}

export interface AreaFeature {
  id: string;
  name: string;
  nameAr: string;
  lat: number;
  lon: number;
  color: string;
  index: number;
  risk: number;
  status: string;
  siteIds: string[];
}

export interface Flow {
  from: [number, number];
  to: [number, number];
  intensity: number;
  color: string;
}

export interface SimHeatPoint {
  lat: number;
  lon: number;
  w: number;
}
export interface Containment {
  lat: number;
  lon: number;
  radiusKm: number;
}

interface MapProps {
  lat: number;
  lon: number;
  zoom: number;
  points: Array<{ lat: number; lng: number; intensity: number }>;
  sites?: SiteFeature[];
  flows?: Flow[];
  lang?: string;
  focus?: { lat: number; lon: number; zoom?: number } | null;
  /** click-to-seed outbreak simulator */
  simMode?: boolean;
  simActive?: boolean;
  onSeed?: (lat: number, lon: number) => void;
  simSeed?: { lat: number; lon: number } | null;
  simDay?: number;
  simHeat?: SimHeatPoint[];
  containment?: Containment | null;
  onSiteClick?: (id: string) => void;
  /** symptom lens: draw clear/at-risk status rings on sites */
  symptomActive?: boolean;
  /** two-level areas: area markers by default, drill into one to see its sites */
  areas?: AreaFeature[];
  selectedArea?: string | null;
  onAreaClick?: (id: string) => void;
}

const REDUCED =
  typeof window !== "undefined" && window.matchMedia
    ? window.matchMedia("(prefers-reduced-motion: reduce)").matches
    : false;

const hexRgb = (hex: string): [number, number, number] => {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};
const hexA = (hex: string, a: number): string => {
  const [r, g, b] = hexRgb(hex);
  return `rgba(${r},${g},${b},${a})`;
};

// glow ramp for the heat FIELD - brightness ascends with magnitude so hotter
// areas read as brighter under the luminous 'screen' blend on satellite.
const GLOW: Array<[number, string]> = [
  [0, "#ffe08a"],
  [0.33, "#fdb833"],
  [0.55, "#f3722c"],
  [0.78, "#ef3340"],
  [1, "#ff2448"],
];
const glowColor = (frac: number): string => {
  const v = Math.max(0, Math.min(1, frac));
  let c = GLOW[0][1];
  for (const [m, col] of GLOW) if (v >= m) c = col;
  return c;
};

// web-mercator ground resolution (metres per CSS pixel) at a latitude + zoom
const metresPerPixel = (lat: number, zoom: number): number =>
  (156543.03392 * Math.cos((lat * Math.PI) / 180)) / Math.pow(2, zoom);

const ESRI = "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}";
const ESRI_REF = "https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}";
const ESRI_ATTR = "Imagery © Esri, Maxar, Earthstar Geographics";

const PITCH = 20;
const BEARING = -12;
const HIT_PX = 17;

// satellite only (Esri World Imagery) + Esri reference labels (same keyless host)
const buildStyle = (): any => ({
  version: 8,
  sources: {
    base: { type: "raster", tiles: [ESRI], tileSize: 256, maxzoom: 19, attribution: ESRI_ATTR },
    labels: { type: "raster", tiles: [ESRI_REF], tileSize: 256, maxzoom: 19, attribution: ESRI_ATTR },
  },
  layers: [
    // theme-coloured ground so no white tile shows at the horizon under pitch
    { id: "sky", type: "background", paint: { "background-color": "#06200f" } },
    { id: "base", type: "raster", source: "base" },
    // place labels: subtle, and only once zoomed in so area badges lead at city zoom
    { id: "labels", type: "raster", source: "labels", minzoom: 11, paint: { "raster-opacity": 0.5 } },
  ],
});

/** Circular cordon polygon for the containment zone (GL layer). */
const circleFC = (c: Containment | null) => {
  if (!c) return { type: "FeatureCollection" as const, features: [] };
  const steps = 72;
  const latR = c.radiusKm / 110.574;
  const lonR = c.radiusKm / (111.32 * Math.cos((c.lat * Math.PI) / 180));
  const ring: Array<[number, number]> = [];
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * 2 * Math.PI;
    ring.push([c.lon + lonR * Math.cos(t), c.lat + latR * Math.sin(t)]);
  }
  return {
    type: "FeatureCollection" as const,
    features: [{ type: "Feature" as const, properties: {}, geometry: { type: "Polygon" as const, coordinates: [ring] } }],
  };
};

const SEED_KEYFRAMES = "map-seed-ping";
const ensureSeedStyle = () => {
  if (typeof document === "undefined" || document.getElementById(SEED_KEYFRAMES)) return;
  const el = document.createElement("style");
  el.id = SEED_KEYFRAMES;
  el.textContent =
    "@keyframes mapSeedPing{0%{transform:scale(1);opacity:.8}70%{transform:scale(3.4);opacity:0}100%{opacity:0}}";
  document.head.appendChild(el);
};
const makeSeedEl = (): HTMLDivElement => {
  ensureSeedStyle();
  const wrap = document.createElement("div");
  wrap.style.cssText = "position:relative;width:18px;height:18px;pointer-events:none";
  const ping = document.createElement("div");
  ping.style.cssText =
    "position:absolute;inset:0;border-radius:50%;background:#EF3340;animation:mapSeedPing 1.8s ease-out infinite";
  const dot = document.createElement("div");
  dot.style.cssText =
    "position:absolute;inset:4px;border-radius:50%;background:#EF3340;border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.4)";
  wrap.appendChild(ping);
  wrap.appendChild(dot);
  return wrap;
};

interface Blob {
  lat: number;
  lon: number;
  radiusM: number;
  color: string;
  alpha: number;
  weight: number;
}

const MapComponent: React.FC<MapProps> = React.memo(
  ({ lat, lon, zoom, points, sites, flows, lang, focus, simMode, simActive, onSeed, simSeed, simDay, simHeat, containment, onSiteClick, symptomActive, areas, selectedArea, onAreaClick }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const fieldCanvasRef = useRef<HTMLCanvasElement>(null);
    const markerCanvasRef = useRef<HTMLCanvasElement>(null);
    const mapRef = useRef<maplibregl.Map | null>(null);
    const pointsRef = useRef(points);
    pointsRef.current = points;
    const sitesRef = useRef<SiteFeature[]>(sites || []);
    sitesRef.current = sites || [];
    const flowsRef = useRef<Flow[]>(flows || []);
    flowsRef.current = flows || [];
    const simHeatRef = useRef<SimHeatPoint[]>(simHeat || []);
    simHeatRef.current = simHeat || [];
    const simActiveRef = useRef(!!simActive);
    simActiveRef.current = !!simActive;
    const langRef = useRef(lang || "en");
    langRef.current = lang || "en";
    const popupRef = useRef<maplibregl.Popup | null>(null);
    const simModeRef = useRef(!!simMode);
    simModeRef.current = !!simMode;
    const onSeedRef = useRef(onSeed);
    onSeedRef.current = onSeed;
    const onSiteClickRef = useRef(onSiteClick);
    onSiteClickRef.current = onSiteClick;
    const containmentRef = useRef<Containment | null>(containment || null);
    containmentRef.current = containment || null;
    const seedMarkerRef = useRef<maplibregl.Marker | null>(null);
    const hoverRef = useRef<string | null>(null);
    const symptomActiveRef = useRef(!!symptomActive);
    symptomActiveRef.current = !!symptomActive;
    const simSeedRef = useRef(simSeed || null);
    simSeedRef.current = simSeed || null;
    const simDayRef = useRef(simDay || 0);
    simDayRef.current = simDay || 0;
    const areasRef = useRef<AreaFeature[]>(areas || []);
    areasRef.current = areas || [];
    const selectedAreaRef = useRef<string | null>(selectedArea || null);
    selectedAreaRef.current = selectedArea || null;
    const onAreaClickRef = useRef(onAreaClick);
    onAreaClickRef.current = onAreaClick;

    const addContain = useCallback((map: maplibregl.Map) => {
      if (!map.getSource("contain")) {
        map.addSource("contain", { type: "geojson", data: circleFC(containmentRef.current) as any });
        map.addLayer({ id: "contain-fill", type: "fill", source: "contain", paint: { "fill-color": "#009639", "fill-opacity": 0.1 } } as any);
        map.addLayer({
          id: "contain-line",
          type: "line",
          source: "contain",
          paint: { "line-color": "#009639", "line-width": 2.2, "line-dasharray": [2, 2], "line-opacity": 0.95 },
        } as any);
      }
    }, []);

    // nearest site to a screen point, within HIT_PX (limited to the drilled area)
    const hitSite = useCallback((pt: { x: number; y: number }): SiteFeature | null => {
      const map = mapRef.current;
      if (!map) return null;
      const sel = selectedAreaRef.current;
      const area = sel ? areasRef.current.find((a) => a.id === sel) : null;
      const allow = area ? new Set(area.siteIds) : null;
      let best: SiteFeature | null = null;
      let bestD = HIT_PX * HIT_PX;
      for (const s of sitesRef.current) {
        if (s.type === "kiosk") continue;
        if (allow && !allow.has(s.id)) continue;
        const p = map.project([s.lon, s.lat] as any);
        const d = (p.x - pt.x) * (p.x - pt.x) + (p.y - pt.y) * (p.y - pt.y);
        if (d < bestD) {
          bestD = d;
          best = s;
        }
      }
      return best;
    }, []);

    // nearest area marker to a screen point (larger hit target)
    const hitArea = useCallback((pt: { x: number; y: number }): AreaFeature | null => {
      const map = mapRef.current;
      if (!map) return null;
      let best: AreaFeature | null = null;
      let bestD = 44 * 44;
      for (const a of areasRef.current) {
        const p = map.project([a.lon, a.lat] as any);
        const d = (p.x - pt.x) * (p.x - pt.x) + (p.y - pt.y) * (p.y - pt.y);
        if (d < bestD) {
          bestD = d;
          best = a;
        }
      }
      return best;
    }, []);

    const showAreaPopup = useCallback((a: AreaFeature) => {
      const map = mapRef.current;
      const popup = popupRef.current;
      if (!map || !popup) return;
      const nm = langRef.current === "ar" ? a.nameAr : a.name;
      const n = a.siteIds.filter((id) => id.indexOf("kiosk") < 0).length;
      const html =
        `<div style="font-family:var(--font-ui);min-width:150px;color:#e9eef8">` +
        `<div style="display:flex;align-items:center;gap:7px;font-weight:800;font-size:12.5px;margin-bottom:5px"><span style="width:9px;height:9px;border-radius:50%;background:${a.color};flex:none"></span>${nm}</div>` +
        `<div style="display:flex;justify-content:space-between;font-size:11px;color:#b3b6b1"><span>area risk</span><b style="color:${a.color}">${a.index}</b></div>` +
        `<div style="display:flex;justify-content:space-between;font-size:11px;color:#b3b6b1"><span>sites</span><b>${n}</b></div>` +
        `<div style="font-size:9px;color:#7f8ba3;margin-top:3px;text-transform:uppercase;letter-spacing:.4px">Tap to drill in</div></div>`;
      popup.setLngLat([a.lon, a.lat]).setHTML(html).addTo(map);
    }, []);

    const showPopup = useCallback((s: SiteFeature) => {
      const map = mapRef.current;
      const popup = popupRef.current;
      if (!map || !popup) return;
      const nm = langRef.current === "ar" ? s.nameAr : s.name;
      const html =
        `<div style="font-family:var(--font-ui);min-width:150px;color:#e9eef8">` +
        `<div style="display:flex;align-items:center;gap:7px;font-weight:800;font-size:12.5px;margin-bottom:5px"><span style="width:9px;height:9px;border-radius:50%;background:${s.color};flex:none"></span>${nm}</div>` +
        `<div style="display:flex;justify-content:space-between;font-size:11px;color:#b3b6b1"><span>risk index</span><b style="color:${s.color}">${s.index}</b></div>` +
        `<div style="display:flex;justify-content:space-between;font-size:11px;color:#b3b6b1"><span>tier</span><b style="color:${s.color};text-transform:capitalize">${s.tier}</b></div>` +
        `<div style="display:flex;justify-content:space-between;font-size:11px;color:#b3b6b1"><span>hotspot prob.</span><b style="color:${s.color}">${s.prob}%</b></div>` +
        `<div style="font-size:9px;color:#7f8ba3;margin-top:3px;text-transform:uppercase;letter-spacing:.4px">Modelled</div></div>`;
      popup.setLngLat([s.lon, s.lat]).setHTML(html).addTo(map);
    }, []);

    // init once
    useEffect(() => {
      if (!containerRef.current || mapRef.current) return;
      const map = new maplibregl.Map({
        container: containerRef.current,
        style: buildStyle(),
        center: [lon, lat],
        zoom: REDUCED ? zoom : Math.max(3, zoom - 2.6),
        pitch: REDUCED ? PITCH : 12,
        bearing: BEARING,
        maxPitch: 75,
        attributionControl: false,
      });
      mapRef.current = map;
      map.addControl(new maplibregl.AttributionControl({ compact: true }), "bottom-right");
      map.dragRotate.enable();
      map.touchZoomRotate.enableRotation();

      popupRef.current = new maplibregl.Popup({ closeButton: false, closeOnClick: false, offset: 16 });

      map.on("load", () => {
        addContain(map);
        if (!REDUCED) {
          map.flyTo({ center: [lon, lat], zoom, pitch: PITCH, bearing: BEARING, duration: 2400, curve: 1.6, essential: true });
        }
      });

      // in area mode (no drill), hover/click areas; once drilled, hover/click sites
      const areaMode = () => !!(areasRef.current.length && !selectedAreaRef.current) && !simModeRef.current;

      map.on("mousemove", (e: any) => {
        if (areaMode()) {
          const a = hitArea(e.point);
          hoverRef.current = a ? a.id : null;
          if (a) {
            map.getCanvas().style.cursor = "pointer";
            showAreaPopup(a);
          } else {
            map.getCanvas().style.cursor = "";
            if (popupRef.current) popupRef.current.remove();
          }
          return;
        }
        const hit = hitSite(e.point);
        hoverRef.current = hit ? hit.id : null;
        if (hit) {
          map.getCanvas().style.cursor = "pointer";
          showPopup(hit);
        } else {
          map.getCanvas().style.cursor = simModeRef.current ? "crosshair" : "";
          if (popupRef.current) popupRef.current.remove();
        }
      });
      map.on("mouseout", () => {
        hoverRef.current = null;
        if (popupRef.current) popupRef.current.remove();
      });
      map.on("click", (e: any) => {
        if (simModeRef.current && onSeedRef.current) {
          onSeedRef.current(e.lngLat.lat, e.lngLat.lng);
          return;
        }
        if (areaMode()) {
          const a = hitArea(e.point);
          if (a && onAreaClickRef.current) onAreaClickRef.current(a.id);
          return;
        }
        const hit = hitSite(e.point);
        if (hit) {
          map.flyTo({ center: [hit.lon, hit.lat], zoom: 13.5, pitch: PITCH, bearing: BEARING, duration: 1200, essential: true });
          if (onSiteClickRef.current) onSiteClickRef.current(hit.id);
        }
      });

      const onResize = () => map.resize();
      window.addEventListener("resize", onResize);

      // ── field + marker + flow renderer ─────────────────────────────
      const fieldCanvas = fieldCanvasRef.current;
      const markerCanvas = markerCanvasRef.current;
      const fctx = fieldCanvas ? fieldCanvas.getContext("2d") : null;
      const mctx = markerCanvas ? markerCanvas.getContext("2d") : null;
      let raf = 0;
      let phase = 0;
      let last = 0;

      const sizeCanvases = () => {
        const gl = map.getCanvas();
        const dpr = window.devicePixelRatio || 1;
        [fieldCanvas, markerCanvas].forEach((cv) => {
          if (!cv) return;
          cv.width = gl.clientWidth * dpr;
          cv.height = gl.clientHeight * dpr;
          cv.style.width = gl.clientWidth + "px";
          cv.style.height = gl.clientHeight + "px";
          const c = cv.getContext("2d");
          if (c) c.setTransform(dpr, 0, 0, dpr, 0, 0);
        });
      };

      const drawField = (w: number, h: number) => {
        if (!fctx) return;
        fctx.clearRect(0, 0, w, h);
        const z = map.getZoom();
        const blobs: Blob[] = [];
        if (simActiveRef.current) {
          for (const p of simHeatRef.current) {
            if (p.w <= 0.003) continue;
            const frac = Math.min(1, p.w * 3.6);
            blobs.push({ lat: p.lat, lon: p.lon, radiusM: 1600 + Math.min(1, p.w * 8) * 5000, color: glowColor(frac), alpha: Math.min(0.78, 0.26 + p.w * 5), weight: p.w });
          }
        } else {
          for (const s of sitesRef.current) {
            if (s.type === "kiosk" || s.risk < 0.012) continue;
            const frac = Math.min(1, s.risk / 0.28);
            blobs.push({ lat: s.lat, lon: s.lon, radiusM: 2600 + Math.min(0.32, s.risk) * 12000, color: glowColor(frac), alpha: Math.min(0.7, 0.2 + s.risk * 2.2), weight: s.risk });
          }
          // real screening density: aggregated grid cells, glow scales with the
          // per-cell count (p.intensity) instead of a uniform faint dot.
          for (const p of pointsRef.current) {
            const count = Math.max(1, p.intensity || 1);
            const frac = Math.min(1, count / 30);
            blobs.push({ lat: p.lat, lon: p.lng, radiusM: 900 + frac * 3200, color: glowColor(frac), alpha: Math.min(0.6, 0.2 + frac * 0.45), weight: count });
          }
        }
        blobs.sort((a, b) => a.weight - b.weight);
        // luminous glow: areas merge and brighten with intensity on the dark satellite
        fctx.globalCompositeOperation = "screen";
        for (const b of blobs) {
          const pp = map.project([b.lon, b.lat] as any);
          const rpx = Math.max(22, b.radiusM / metresPerPixel(b.lat, z));
          if (pp.x < -rpx || pp.y < -rpx || pp.x > w + rpx || pp.y > h + rpx) continue;
          const g = fctx.createRadialGradient(pp.x, pp.y, 0, pp.x, pp.y, rpx);
          g.addColorStop(0, hexA(b.color, b.alpha));
          g.addColorStop(0.5, hexA(b.color, b.alpha * 0.5));
          g.addColorStop(1, hexA(b.color, 0));
          fctx.fillStyle = g;
          fctx.beginPath();
          fctx.arc(pp.x, pp.y, rpx, 0, Math.PI * 2);
          fctx.fill();
        }
        fctx.globalCompositeOperation = "source-over";
      };

      const drawFlows = (dt: number) => {
        if (!mctx) return;
        if (!REDUCED) phase = (phase + dt * 0.5) % 1;
        for (const f of flowsRef.current) {
          const a = map.project({ lng: f.from[0], lat: f.from[1] } as any);
          const b = map.project({ lng: f.to[0], lat: f.to[1] } as any);
          mctx.setLineDash([4, 6]);
          mctx.lineWidth = 1.2;
          mctx.strokeStyle = hexA(f.color, 0.3);
          mctx.beginPath();
          mctx.moveTo(a.x, a.y);
          mctx.lineTo(b.x, b.y);
          mctx.stroke();
          mctx.setLineDash([]);
          const strength = Math.min(1, f.intensity);
          if (REDUCED) continue;
          const n = 2 + Math.round(strength * 3);
          for (let k = 0; k < n; k++) {
            const t = (phase * (0.5 + strength) + k / n) % 1;
            const x = a.x + (b.x - a.x) * t;
            const y = a.y + (b.y - a.y) * t;
            mctx.globalAlpha = 0.3 + 0.6 * strength * (1 - Math.abs(t - 0.5) * 1.4);
            mctx.fillStyle = f.color;
            mctx.beginPath();
            mctx.arc(x, y, 2 + strength * 2.5, 0, Math.PI * 2);
            mctx.fill();
            mctx.globalAlpha = 1;
          }
        }
      };

      const drawAreaMarkers = () => {
        if (!mctx) return;
        const NAME_F = "650 13px 'Bricolage Grotesque', ui-sans-serif, sans-serif";
        const SUB_F = "500 11px 'IBM Plex Sans', ui-sans-serif, sans-serif";
        const VAL_F = "700 17px 'Bricolage Grotesque', ui-sans-serif, sans-serif";
        const padX = 13;
        const gap = 14;
        // 1. measure every tile and record its ideal (centred) position
        const tiles = areasRef.current.map((a) => {
          const p = map.project([a.lon, a.lat] as any);
          const nm = langRef.current === "ar" ? a.nameAr : a.name;
          mctx.font = NAME_F;
          const nw = mctx.measureText(nm).width;
          mctx.font = SUB_F;
          const sw = mctx.measureText(a.status).width;
          mctx.font = VAL_F;
          const vw = mctx.measureText(String(a.index)).width;
          const textW = Math.max(nw, sw);
          const bw = padX + 15 + textW + gap + vw + padX;
          const bh = 44;
          return { a, nm, cx: p.x, cy: p.y, bw, bh, x: p.x - bw / 2, y: p.y - bh / 2, nudged: false };
        });
        // 2. resolve overlaps by nudging tiles downward (top-to-bottom, greedy)
        tiles.sort((t1, t2) => t1.cy - t2.cy);
        const placed: Array<{ x: number; y: number; bw: number; bh: number }> = [];
        const M = 6; // min gap between tiles
        for (const t of tiles) {
          const hits = (yy: number) =>
            placed.some(
              (q) => !(t.x + t.bw < q.x - M || t.x > q.x + q.bw + M || yy + t.bh < q.y - M || yy > q.y + q.bh + M),
            );
          let y = t.y;
          let guard = 0;
          while (hits(y) && guard < 48) {
            y += 7;
            guard++;
          }
          t.nudged = Math.abs(y - t.y) > 3;
          t.y = y;
          placed.push({ x: t.x, y, bw: t.bw, bh: t.bh });
        }
        // 3. leader lines from nudged tiles back to their true centroid (under tiles)
        for (const t of tiles) {
          if (!t.nudged) continue;
          mctx.beginPath();
          mctx.moveTo(t.cx, t.cy);
          mctx.lineTo(t.x + t.bw / 2, t.y);
          mctx.strokeStyle = "rgba(255,255,255,0.28)";
          mctx.lineWidth = 1;
          mctx.stroke();
          mctx.beginPath();
          mctx.arc(t.cx, t.cy, 3, 0, Math.PI * 2);
          mctx.fillStyle = t.a.color;
          mctx.fill();
        }
        // 4. draw the tiles
        for (const t of tiles) {
          const a = t.a;
          const hovered = hoverRef.current === a.id;
          const bx = t.x;
          const by = t.y;
          const bw = t.bw;
          const bh = t.bh;
          const r = 11;
          mctx.beginPath();
          (mctx as any).roundRect ? (mctx as any).roundRect(bx, by, bw, bh, r) : mctx.rect(bx, by, bw, bh);
          mctx.fillStyle = hovered ? "rgba(11,11,12,0.94)" : "rgba(11,11,12,0.86)";
          mctx.fill();
          if (hovered) {
            // UAE red focus ring on the active tile
            mctx.shadowColor = "rgba(239,51,64,0.55)";
            mctx.shadowBlur = 16;
          }
          // neutral white border (risk is shown by the colour dot + value), red on hover
          mctx.lineWidth = hovered ? 2.4 : 1.5;
          mctx.strokeStyle = hovered ? "#ef3340" : "rgba(255,255,255,0.16)";
          mctx.stroke();
          mctx.shadowBlur = 0;
          // tier-colour risk dot
          mctx.beginPath();
          mctx.arc(bx + padX + 4, by + 22, 4, 0, Math.PI * 2);
          mctx.fillStyle = a.color;
          mctx.fill();
          mctx.textAlign = "left";
          mctx.textBaseline = "alphabetic";
          mctx.font = NAME_F;
          mctx.fillStyle = "#ffffff";
          mctx.fillText(t.nm, bx + padX + 15, by + 19);
          mctx.font = SUB_F;
          mctx.fillStyle = "#93b8a2";
          mctx.fillText(a.status, bx + padX + 15, by + 34);
          mctx.font = VAL_F;
          mctx.fillStyle = a.color;
          mctx.textAlign = "right";
          mctx.textBaseline = "middle";
          mctx.fillText(String(a.index), bx + bw - padX, by + bh / 2 + 1);
          mctx.textAlign = "start";
          mctx.textBaseline = "alphabetic";
        }
      };

      const drawMarkers = () => {
        if (!mctx) return;
        if (areasRef.current.length && !selectedAreaRef.current) {
          drawAreaMarkers();
          return;
        }
        const sel = selectedAreaRef.current;
        const area = sel ? areasRef.current.find((a) => a.id === sel) : null;
        const allow = area ? new Set(area.siteIds) : null;
        const ranked = sitesRef.current
          .filter((s) => s.type !== "kiosk" && (!allow || allow.has(s.id)))
          .slice()
          .sort((a, b) => b.risk - a.risk);
        const labelled = new Set(ranked.filter((s) => s.index >= 7).slice(0, 8).map((s) => s.id));
        for (const s of ranked) {
          const p = map.project([s.lon, s.lat] as any);
          const hovered = hoverRef.current === s.id;
          const r = 4 + Math.min(0.3, s.risk) * 26 + (hovered ? 2 : 0);
          // soft halo
          mctx.beginPath();
          mctx.arc(p.x, p.y, r + 3, 0, Math.PI * 2);
          mctx.fillStyle = hexA(s.color, 0.18);
          mctx.fill();
          // dot
          mctx.beginPath();
          mctx.arc(p.x, p.y, r, 0, Math.PI * 2);
          mctx.fillStyle = s.color;
          mctx.globalAlpha = 0.96;
          mctx.fill();
          mctx.globalAlpha = 1;
          mctx.lineWidth = hovered ? 2.4 : 1.6;
          mctx.strokeStyle = "#ffffff";
          mctx.stroke();
          // symptom lens: clear (green) vs at-risk (red) status ring
          if (symptomActiveRef.current) {
            mctx.beginPath();
            mctx.arc(p.x, p.y, r + 4.5, 0, Math.PI * 2);
            mctx.lineWidth = 2.4;
            mctx.strokeStyle = s.atRisk ? "#ff3b47" : "#19b65c";
            mctx.stroke();
          }
          // value label for the hottest sites (or on hover): "how much" here
          if (labelled.has(s.id) || hovered) {
            const txt = String(s.index);
            mctx.font = "700 11px ui-monospace, 'SF Mono', 'Cascadia Mono', monospace";
            const tw = mctx.measureText(txt).width;
            const bx = p.x + r + 4;
            const by = p.y - 9;
            const pad = 4;
            mctx.fillStyle = "rgba(255,255,255,0.92)";
            mctx.strokeStyle = hexA(s.color, 0.6);
            mctx.lineWidth = 1;
            const bw = tw + pad * 2;
            const bh = 16;
            mctx.beginPath();
            (mctx as any).roundRect ? (mctx as any).roundRect(bx, by, bw, bh, 5) : mctx.rect(bx, by, bw, bh);
            mctx.fill();
            mctx.stroke();
            mctx.fillStyle = s.color;
            mctx.textBaseline = "middle";
            mctx.fillText(txt, bx + pad, by + bh / 2 + 0.5);
          }
        }
      };

      // expanding outbreak wavefront from the seed (sonar rings + day badge)
      const drawWavefront = (ts: number) => {
        if (!mctx || !simActiveRef.current || !simSeedRef.current) return;
        const seed = simSeedRef.current;
        const c = map.project([seed.lon, seed.lat] as any);
        const z = map.getZoom();
        const frontPx = (Math.max(0.5, simDayRef.current * 1.8) * 1000) / metresPerPixel(seed.lat, z);
        // leading front
        mctx.beginPath();
        mctx.arc(c.x, c.y, frontPx, 0, Math.PI * 2);
        mctx.setLineDash([6, 5]);
        mctx.lineWidth = 2;
        mctx.strokeStyle = "rgba(243,114,44,0.6)";
        mctx.stroke();
        mctx.setLineDash([]);
        // sonar pulses rippling out to the front
        if (!REDUCED) {
          for (let k = 0; k < 3; k++) {
            const tt = ((ts / 2000) + k / 3) % 1;
            mctx.beginPath();
            mctx.arc(c.x, c.y, tt * frontPx, 0, Math.PI * 2);
            mctx.lineWidth = 1.6;
            mctx.strokeStyle = `rgba(255,120,60,${(1 - tt) * 0.4})`;
            mctx.stroke();
          }
        }
        // day badge near the seed
        const label = "Day " + Math.round(simDayRef.current);
        mctx.font = "700 11px ui-monospace, 'SF Mono', monospace";
        const tw = mctx.measureText(label).width;
        const bx = c.x + 12;
        const by = c.y - 26;
        mctx.beginPath();
        (mctx as any).roundRect ? (mctx as any).roundRect(bx, by, tw + 14, 18, 6) : mctx.rect(bx, by, tw + 14, 18);
        mctx.fillStyle = "rgba(14,15,15,0.9)";
        mctx.fill();
        mctx.strokeStyle = "rgba(243,114,44,0.7)";
        mctx.lineWidth = 1;
        mctx.stroke();
        mctx.fillStyle = "#f3722c";
        mctx.textBaseline = "middle";
        mctx.fillText(label, bx + 7, by + 9.5);
      };

      const render = (ts: number) => {
        const dt = last ? (ts - last) / 1000 : 0;
        last = ts;
        const w = map.getCanvas().clientWidth;
        const h = map.getCanvas().clientHeight;
        drawField(w, h);
        if (mctx) mctx.clearRect(0, 0, w, h);
        drawFlows(dt);
        drawMarkers();
        drawWavefront(ts);
        raf = requestAnimationFrame(render);
      };

      sizeCanvases();
      map.on("resize", sizeCanvases);
      raf = requestAnimationFrame(render);

      return () => {
        cancelAnimationFrame(raf);
        window.removeEventListener("resize", onResize);
        map.off("resize", sizeCanvases);
        map.remove();
        mapRef.current = null;
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // fly on location change
    useEffect(() => {
      const map = mapRef.current;
      if (!map) return;
      map.flyTo({ center: [lon, lat], zoom, pitch: PITCH, bearing: BEARING, duration: 1500, essential: true });
    }, [lat, lon, zoom]);

    // explicit focus (hotspot / network / nudge click)
    useEffect(() => {
      const map = mapRef.current;
      if (!map || !focus) return;
      map.flyTo({ center: [focus.lon, focus.lat], zoom: focus.zoom || 13.5, pitch: PITCH, bearing: BEARING, duration: 1300, essential: true });
    }, [focus]);

    // containment cordon ring
    useEffect(() => {
      const map = mapRef.current;
      if (!map) return;
      const update = () => {
        const s = map.getSource("contain") as maplibregl.GeoJSONSource | undefined;
        if (s) s.setData(circleFC(containment || null) as any);
      };
      if (map.isStyleLoaded()) update();
      else map.once("load", update);
    }, [containment]);

    // crosshair cursor while seeding
    useEffect(() => {
      const map = mapRef.current;
      if (!map) return;
      if (!hoverRef.current) map.getCanvas().style.cursor = simMode ? "crosshair" : "";
    }, [simMode]);

    // seed epicentre marker (pulsing)
    useEffect(() => {
      const map = mapRef.current;
      if (!map) return;
      if (!simSeed) {
        if (seedMarkerRef.current) {
          seedMarkerRef.current.remove();
          seedMarkerRef.current = null;
        }
        return;
      }
      if (!seedMarkerRef.current) {
        seedMarkerRef.current = new maplibregl.Marker({ element: makeSeedEl(), anchor: "center" });
      }
      seedMarkerRef.current.setLngLat([simSeed.lon, simSeed.lat]).addTo(map);
    }, [simSeed]);

    return (
      <div style={{ position: "relative", width: "100%", height: "100%" }}>
        <div ref={containerRef} style={{ position: "absolute", inset: 0 }} />
        <canvas ref={fieldCanvasRef} aria-hidden="true" style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 1 }} />
        <canvas ref={markerCanvasRef} aria-hidden="true" style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 2 }} />
      </div>
    );
  },
);

export default MapComponent;
