import React, { useMemo } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { SITES, METRO_RED, METRO_GREEN, SITE_MAP } from "../../data/demo/sites";
import { nodeRiskAt, tierForFraction, RISK_TIER_MAP, INDEX_SCALE } from "../../model/forecast";

const W = 560;
const H = 440;
const PAD = 30;

const graphSites = SITES.filter((s) => s.type !== "kiosk");
const lats = graphSites.map((s) => s.lat);
const lons = graphSites.map((s) => s.lon);
const LAT0 = Math.min.apply(null, lats);
const LAT1 = Math.max.apply(null, lats);
const LON0 = Math.min.apply(null, lons);
const LON1 = Math.max.apply(null, lons);
const px = (lon: number) => PAD + ((lon - LON0) / (LON1 - LON0 || 1)) * (W - 2 * PAD);
const py = (lat: number) => PAD + ((LAT1 - lat) / (LAT1 - LAT0 || 1)) * (H - 2 * PAD);

const edges: Array<[string, string, string]> = [];
METRO_RED.forEach((id, k) => { if (k < METRO_RED.length - 1) edges.push([id, METRO_RED[k + 1], "#EF3340"]); });
METRO_GREEN.forEach((id, k) => { if (k < METRO_GREEN.length - 1) edges.push([id, METRO_GREEN[k + 1], "#00843d"]); });

const Wrap = styled.div`
  display: flex;
  gap: 18px;
  align-items: stretch;
  @media (max-width: 860px) {
    flex-direction: column;
  }
`;
const GraphCol = styled.div`
  flex: 1;
  min-width: 0;
`;
const Caption = styled.div`
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 10px;
  line-height: 1.45;
`;
const Svg = styled.svg`
  width: 100%;
  height: auto;
  display: block;
  background: rgba(11, 11, 12, 0.5);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  circle {
    cursor: pointer;
  }
`;
const Legend = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin-top: 12px;
  align-items: center;
  .grp {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    font-size: 11px;
    color: var(--muted);
  }
  .lab {
    font-size: 9px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--faint);
  }
  .sw {
    display: inline-flex;
    align-items: center;
    gap: 5px;
  }
  i {
    border-radius: 50%;
    display: inline-block;
  }
  .dotrow {
    display: inline-flex;
    align-items: flex-end;
    gap: 6px;
  }
  .dotrow i {
    background: var(--muted);
  }
`;
const Side = styled.div`
  width: 236px;
  flex: none;
  background: rgba(11, 11, 12, 0.5);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 13px 14px;
  @media (max-width: 860px) {
    width: auto;
  }
  .h {
    font-size: 9.5px;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--faint);
    margin-bottom: 10px;
  }
`;
const Corridor = styled.button`
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  text-align: start;
  background: transparent;
  border: 0;
  border-top: 1px solid var(--border);
  padding: 9px 0;
  cursor: pointer;
  &:first-of-type {
    border-top: 0;
  }
  &:hover .nm {
    color: var(--ink);
  }
  .line {
    width: 4px;
    align-self: stretch;
    border-radius: 999px;
    flex: none;
  }
  .bd {
    flex: 1;
    min-width: 0;
  }
  .nm {
    font-size: 12px;
    font-weight: 600;
    color: var(--ink-2);
    line-height: 1.3;
  }
  .sub {
    font-size: 10.5px;
    color: var(--muted);
    margin-top: 2px;
  }
  .v {
    font-family: var(--font-num);
    font-variant-numeric: tabular-nums;
    font-weight: 700;
    font-size: 15px;
    color: var(--ink);
    flex: none;
  }
`;

interface Props {
  day: number;
  lang: string;
  onSelect: (id: string) => void;
}

const NetworkGraph: React.FC<Props> = ({ day, lang, onSelect }) => {
  const { t } = useTranslation();
  const ar = lang === "ar";
  const tiers = ["low", "moderate", "elevated", "high", "critical"] as const;

  // layout: project by geography, then relax so co-located nodes separate
  const layout = useMemo(() => {
    const nodes = graphSites.map((s) => ({ id: s.id, x: px(s.lon), y: py(s.lat), r: 5 + s.footfall * 11 }));
    const byId: Record<string, (typeof nodes)[number]> = {};
    nodes.forEach((n) => (byId[n.id] = n));
    for (let iter = 0; iter < 90; iter++) {
      for (let i = 0; i < nodes.length; i++) {
        for (let j = i + 1; j < nodes.length; j++) {
          const a = nodes[i];
          const b = nodes[j];
          let dx = b.x - a.x;
          let dy = b.y - a.y;
          let d = Math.sqrt(dx * dx + dy * dy) || 0.01;
          const min = a.r + b.r + 6;
          if (d < min) {
            const push = (min - d) / 2;
            dx /= d;
            dy /= d;
            a.x -= dx * push;
            a.y -= dy * push;
            b.x += dx * push;
            b.y += dy * push;
          }
        }
      }
    }
    // clamp into the viewbox
    nodes.forEach((n) => {
      n.x = Math.max(n.r + 2, Math.min(W - n.r - 2, n.x));
      n.y = Math.max(n.r + 2, Math.min(H - n.r - 2, n.y));
    });
    return byId;
  }, []);

  // label the ~15 busiest sites; the rest reveal their name on hover
  const labelled = useMemo(() => {
    const top = graphSites.slice().sort((a, b) => b.footfall - a.footfall).slice(0, 10);
    return new Set(top.map((s) => s.id));
  }, []);

  // strongest corridors: endpoint footfall x predicted risk at this day
  const corridors = useMemo(() => {
    return edges
      .map(([a, b, color]) => {
        const sa = SITE_MAP[a];
        const sb = SITE_MAP[b];
        if (!sa || !sb) return null;
        const risk = (nodeRiskAt(a, day) + nodeRiskAt(b, day)) / 2;
        const foot = (sa.footfall + sb.footfall) / 2;
        return { a, b, sa, sb, color, strength: Math.round(foot * risk * INDEX_SCALE) };
      })
      .filter(Boolean)
      .sort((x, y) => (y as any).strength - (x as any).strength)
      .slice(0, 6) as Array<{ a: string; b: string; sa: any; sb: any; color: string; strength: number }>;
  }, [day]);

  return (
    <Wrap>
      <GraphCol>
        <Caption>
          {t("network.caption", {
            defaultValue:
              "The mobility graph the model runs on. Node size is footfall, node colour is predicted risk, links are metro corridors. Tap a node to inspect it on the map.",
          })}
        </Caption>
        <Svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={t("rail.network", { defaultValue: "Network graph" })}>
          {edges.map(([a, b, color], i) => {
            const na = layout[a];
            const nb = layout[b];
            if (!na || !nb) return null;
            return <line key={`e${i}`} x1={na.x} y1={na.y} x2={nb.x} y2={nb.y} stroke={color} strokeWidth={1.6} strokeOpacity={0.5} />;
          })}
          {graphSites.map((s) => {
            const n = layout[s.id];
            if (!n) return null;
            const risk = nodeRiskAt(s.id, day);
            const color = RISK_TIER_MAP[tierForFraction(risk)].color;
            const nm = ar ? s.nameAr : s.name;
            return (
              <g key={s.id}>
                <circle cx={n.x} cy={n.y} r={n.r} fill={color} stroke="#ffffff" strokeWidth={1.4} onClick={() => onSelect(s.id)}>
                  <title>{nm}</title>
                </circle>
                {labelled.has(s.id) && (
                  <text x={n.x} y={n.y - n.r - 3} textAnchor="middle" fill="#e6efe9" fontSize={9.5} fontFamily="'IBM Plex Sans', sans-serif" style={{ pointerEvents: "none" }}>
                    {nm.length > 18 ? nm.slice(0, 17) + "…" : nm}
                  </text>
                )}
              </g>
            );
          })}
        </Svg>
        <Legend>
          <span className="grp">
            <span className="lab">{t("network.sizeFootfall", { defaultValue: "Size = footfall" })}</span>
            <span className="dotrow">
              <i style={{ width: 7, height: 7 }} />
              <i style={{ width: 11, height: 11 }} />
              <i style={{ width: 16, height: 16 }} />
            </span>
          </span>
          <span className="grp">
            <span className="lab">{t("network.colourRisk", { defaultValue: "Colour = risk" })}</span>
            {tiers.map((tk) => (
              <span className="sw" key={tk}>
                <i style={{ width: 9, height: 9, background: RISK_TIER_MAP[tk].color }} />
                {t(`fc.tier.${tk}`, { defaultValue: tk })}
              </span>
            ))}
          </span>
        </Legend>
      </GraphCol>

      <Side>
        <div className="h">{t("network.strongest", { defaultValue: "Strongest corridors" })}</div>
        {corridors.map((c) => (
          <Corridor key={`${c.a}-${c.b}`} onClick={() => onSelect(c.a)}>
            <span className="line" style={{ background: c.color }} />
            <span className="bd">
              <div className="nm">
                {(ar ? c.sa.nameAr : c.sa.name)} ↔ {(ar ? c.sb.nameAr : c.sb.name)}
              </div>
              <div className="sub">{c.color === "#EF3340" ? t("network.redLine", { defaultValue: "Red Line" }) : t("network.greenLine", { defaultValue: "Green Line" })}</div>
            </span>
            <span className="v">{c.strength}</span>
          </Corridor>
        ))}
      </Side>
    </Wrap>
  );
};

export default NetworkGraph;
